export default {
  plugins: { "@tailwindcss/postcss": {} },
};

"use client";

import { useState } from "react";
import { TopBar } from "@/components/layout/AppSidebar";
import { Card, CardContent } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Avatar, AvatarFallback } from "@/components/ui/avatar";
import { Progress } from "@/components/ui/progress";
import {
  Table, TableBody, TableCell, TableHead, TableHeader, TableRow,
} from "@/components/ui/table";
import {
  DropdownMenu, DropdownMenuContent, DropdownMenuItem, DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import {
  Search, Plus, LayoutGrid, List, MoreHorizontal,
  Phone, Mail, Tag, Send, Filter,
} from "lucide-react";
import { formatCurrency, formatRelativeTime, getInitials, cn } from "@/lib/utils";
import { useAppStore } from "@/lib/store";
import Link from "next/link";
import AddClientModal from "@/components/clients/AddClientModal";

const TAG_COLORS: Record<string, string> = {
  VIP: "bg-amber-100 text-amber-700",
  Residential: "bg-blue-100 text-blue-700",
  Commercial: "bg-violet-100 text-violet-700",
  Office: "bg-primary/10 text-primary",
  New: "bg-green-100 text-green-700",
};

export default function ClientsPage() {
  const [view, setView] = useState<"table" | "card">("table");
  const [search, setSearch] = useState("");
  const [source, setSource] = useState("all");
  const [drawerOpen, setDrawerOpen] = useState(false);
  const clients = useAppStore((state) => state.clients);

  const filtered = clients.filter((c) => (source === "all" || c.source === source) && (
    c.full_name.toLowerCase().includes(search.toLowerCase()) ||
    c.email?.toLowerCase().includes(search.toLowerCase()) ||
    c.phone.includes(search))
  );

  return (
    <div>
      <TopBar title="Clients" subtitle={`${clients.length} total clients`} />
      <div className="p-6">
        {/* Toolbar */}
        <div className="flex flex-wrap items-center justify-between mb-6 gap-3 rounded-xl border border-border bg-card p-3">
          <div className="relative min-w-[200px] flex-1">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
            <Input
              placeholder="Search by name, email or phone…"
              aria-label="Search clients"
              className="pl-9"
              value={search}
              onChange={(e) => setSearch(e.target.value)}
            />
          </div>
          <div className="flex flex-wrap items-center gap-2">
            <select aria-label="Filter clients by source" value={source} onChange={(e) => setSource(e.target.value)} className="h-10 rounded-lg border border-border bg-card px-3 text-xs">
              <option value="all">All sources</option>
              {[...new Set(clients.map((c) => c.source).filter(Boolean))].map((s) => <option key={s} value={s}>{s}</option>)}
            </select>
            <div className="flex rounded-lg border border-border overflow-hidden">
              <button
                onClick={() => setView("table")}
                aria-label="Client table view"
                aria-pressed={view === "table"}
                className={cn("px-3 py-2 text-sm", view === "table" ? "bg-primary text-white" : "bg-card text-muted-foreground hover:bg-muted")}
              >
                <List className="w-4 h-4" />
              </button>
              <button
                onClick={() => setView("card")}
                aria-label="Client card view"
                aria-pressed={view === "card"}
                className={cn("px-3 py-2 text-sm", view === "card" ? "bg-primary text-white" : "bg-card text-muted-foreground hover:bg-muted")}
              >
                <LayoutGrid className="w-4 h-4" />
              </button>
            </div>
            <Button onClick={() => setDrawerOpen(true)} className="gap-2 gradient-primary border-0">
              <Plus className="w-4 h-4" />
              Add Client
            </Button>
          </div>
        </div>

        {/* Table View */}
        {view === "table" && (
          <Card>
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead>Client</TableHead>
                  <TableHead>Phone</TableHead>
                  <TableHead>Source</TableHead>
                  <TableHead>Tags</TableHead>
                  <TableHead>Active Projects</TableHead>
                  <TableHead>Total Value</TableHead>
                  <TableHead>Last Activity</TableHead>
                  <TableHead className="w-10"></TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {filtered.map((client) => (
                  <TableRow key={client.id} className="cursor-pointer hover:bg-muted/30">
                    <TableCell>
                      <Link href={`/clients/${client.id}`} className="flex items-center gap-3">
                        <Avatar className="w-8 h-8">
                          <AvatarFallback className="text-xs bg-primary/10 text-primary font-semibold">
                            {getInitials(client.full_name)}
                          </AvatarFallback>
                        </Avatar>
                        <div>
                          <p className="font-semibold text-sm text-foreground">{client.full_name}</p>
                          <p className="text-xs text-muted-foreground">{client.email}</p>
                        </div>
                      </Link>
                    </TableCell>
                    <TableCell className="text-sm text-muted-foreground">{client.phone}</TableCell>
                    <TableCell>
                      <Badge variant="secondary" className="capitalize text-xs">{client.source}</Badge>
                    </TableCell>
                    <TableCell>
                      <div className="flex gap-1 flex-wrap">
                        {client.tags.map((tag) => (
                          <span key={tag} className={cn("text-[10px] px-1.5 py-0.5 rounded font-medium", TAG_COLORS[tag] || "bg-slate-100 text-slate-700")}>
                            {tag}
                          </span>
                        ))}
                      </div>
                    </TableCell>
                    <TableCell>
                      <div className="flex items-center gap-2">
                        <div className="w-5 h-5 bg-primary/10 text-primary rounded-full flex items-center justify-center text-[11px] font-bold">
                          {client.active_projects}
                        </div>
                        <span className="text-sm text-muted-foreground">projects</span>
                      </div>
                    </TableCell>
                    <TableCell className="font-semibold text-sm">
                      {client.total_value ? formatCurrency(client.total_value) : "—"}
                    </TableCell>
                    <TableCell className="text-xs text-muted-foreground">
                      {client.last_activity ? formatRelativeTime(client.last_activity) : "—"}
                    </TableCell>
                    <TableCell>
                      <DropdownMenu>
                        <DropdownMenuTrigger className="w-7 h-7 inline-flex items-center justify-center rounded-md hover:bg-muted cursor-pointer border-0 bg-transparent">
                          <MoreHorizontal className="w-4 h-4" />
                        </DropdownMenuTrigger>
                        <DropdownMenuContent align="end">
                          <DropdownMenuItem>
                            <Link href={`/clients/${client.id}`} className="w-full">View Profile</Link>
                          </DropdownMenuItem>
                          <DropdownMenuItem>
                            <Send className="w-3.5 h-3.5 mr-2" /> Send Portal Invite
                          </DropdownMenuItem>
                          <DropdownMenuItem>Edit Client</DropdownMenuItem>
                        </DropdownMenuContent>
                      </DropdownMenu>
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          </Card>
        )}

        {/* Card View */}
        {view === "card" && (
          <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-4">
            {filtered.map((client) => (
              <Link key={client.id} href={`/clients/${client.id}`}>
                <Card className="card-hover cursor-pointer">
                  <CardContent className="p-5">
                    <div className="flex items-start justify-between mb-4">
                      <div className="flex items-center gap-3">
                        <Avatar className="w-11 h-11">
                          <AvatarFallback className="text-sm bg-primary/10 text-primary font-bold">
                            {getInitials(client.full_name)}
                          </AvatarFallback>
                        </Avatar>
                        <div>
                          <p className="font-semibold text-foreground">{client.full_name}</p>
                          <p className="text-xs text-muted-foreground capitalize">{client.source}</p>
                        </div>
                      </div>
                      <div className="flex gap-1 flex-wrap justify-end">
                        {client.tags.slice(0, 2).map((tag) => (
                          <span key={tag} className={cn("text-[10px] px-1.5 py-0.5 rounded font-medium", TAG_COLORS[tag] || "bg-slate-100 text-slate-700")}>
                            {tag}
                          </span>
                        ))}
                      </div>
                    </div>
                    <div className="space-y-1.5 mb-4">
                      <div className="flex items-center gap-2 text-sm text-muted-foreground">
                        <Phone className="w-3.5 h-3.5" />
                        {client.phone}
                      </div>
                      {client.email && (
                        <div className="flex items-center gap-2 text-sm text-muted-foreground">
                          <Mail className="w-3.5 h-3.5" />
                          <span className="truncate">{client.email}</span>
                        </div>
                      )}
                    </div>
                    <div className="flex items-center justify-between pt-3 border-t border-border">
                      <div className="text-center">
                        <p className="text-lg font-bold text-primary">{client.active_projects}</p>
                        <p className="text-[10px] text-muted-foreground">Projects</p>
                      </div>
                      <div className="text-center">
                        <p className="text-lg font-bold text-foreground">
                          {client.total_value ? formatCurrency(client.total_value) : "—"}
                        </p>
                        <p className="text-[10px] text-muted-foreground">Total Value</p>
                      </div>
                      <div className="text-center">
                        <p className="text-xs font-medium text-muted-foreground">
                          {client.last_activity ? formatRelativeTime(client.last_activity) : "—"}
                        </p>
                        <p className="text-[10px] text-muted-foreground">Last active</p>
                      </div>
                    </div>
                  </CardContent>
                </Card>
              </Link>
            ))}
          </div>
        )}

        {/* Empty state */}
        {filtered.length === 0 && (
          <div className="flex flex-col items-center justify-center py-20 text-center">
            <div className="w-14 h-14 bg-muted rounded-2xl flex items-center justify-center mb-4">
              <Tag className="w-6 h-6 text-muted-foreground" />
            </div>
            <h3 className="font-semibold text-foreground mb-1">No clients found</h3>
            <p className="text-sm text-muted-foreground mb-4">Try adjusting your search or add a new client.</p>
            <Button onClick={() => setDrawerOpen(true)} className="gap-2 gradient-primary border-0">
              <Plus className="w-4 h-4" />
              Add First Client
            </Button>
          </div>
        )}
      </div>

      <AddClientModal open={drawerOpen} onClose={() => setDrawerOpen(false)} />
    </div>
  );
}

"use client";

import { useState } from "react";
import Link from "next/link";
import { TopBar } from "@/components/layout/AppSidebar";
import { Card, CardContent } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import {
  Table, TableBody, TableCell, TableHead, TableHeader, TableRow,
} from "@/components/ui/table";
import {
  DropdownMenu, DropdownMenuContent, DropdownMenuItem, DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import {
  Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription, DialogFooter,
} from "@/components/ui/dialog";
import {
  Search, Plus, MoreHorizontal, Download, IndianRupee, Clock, ArrowUpRight,
  CheckCircle2, AlertCircle, Building2, CreditCard, Check, Receipt, Printer
} from "lucide-react";
import { useAppStore } from "@/lib/store";
import { formatCurrency, formatDate, getStatusColor, cn } from "@/lib/utils";
import { Invoice, PAYMENT_MODE_LABELS, type PaymentMode } from "@/types";
import { canRecordPayments } from "@/lib/permissions";

export default function InvoicesPage() {
  const { invoices, projects, clients, studioSettings, addInvoice, recordPayment, me } = useAppStore();

  const [search, setSearch] = useState("");
  const [statusFilter, setStatusFilter] = useState<string>("all");

  // Create Invoice Modal State
  const [showCreateModal, setShowCreateModal] = useState(false);
  const [selectedProjectId, setSelectedProjectId] = useState(projects[0]?.id || "");
  const [invoiceTitle, setInvoiceTitle] = useState("Carpentry & Wardrobe Milestone (40%)");
  const [subtotal, setSubtotal] = useState(250000);
  const [dueDate, setDueDate] = useState("2025-01-15");

  // Record Payment Modal State
  const [paymentInvoice, setPaymentInvoice] = useState<Invoice | null>(null);
  const [paymentAmount, setPaymentAmount] = useState<number>(0);
  const [paymentMode, setPaymentMode] = useState<PaymentMode>("bank_transfer");
  const [paymentRef, setPaymentRef] = useState<string>("");
  const [paymentDate, setPaymentDate] = useState<string>("");

  // Invoice PDF View Modal State
  const [viewInvoice, setViewInvoice] = useState<Invoice | null>(null);

  const filtered = invoices.filter((inv) => {
    const matchesSearch =
      (inv.invoice_number || "").toLowerCase().includes(search.toLowerCase()) ||
      inv.client_name.toLowerCase().includes(search.toLowerCase()) ||
      inv.project_name.toLowerCase().includes(search.toLowerCase());

    const matchesStatus =
      statusFilter === "all" || inv.status.toLowerCase() === statusFilter.toLowerCase();

    return matchesSearch && matchesStatus;
  });

  const totalInvoiced = invoices.reduce((sum, inv) => sum + inv.total_amount, 0);
  const totalPaid = invoices.reduce((sum, inv) => sum + inv.amount_paid, 0);
  const totalOutstanding = invoices.reduce((sum, inv) => sum + inv.amount_due, 0);
  const overdueCount = invoices.filter((inv) => inv.status === "overdue").length;

  const handleCreateInvoice = async (e: React.FormEvent) => {
    e.preventDefault();
    const proj = projects.find((p) => p.id === selectedProjectId);
    if (!proj) return;

    const gstPercent = studioSettings.gst_rate;
    const r = await addInvoice({
      project_id: proj.id,
      subtotal,
      discount: 0,
      gst_rate: gstPercent,
      due_date: dueDate,
      notes: invoiceTitle,
      send: true,
    });
    if (r.ok) setShowCreateModal(false);
  };

  const openPaymentModal = (inv: Invoice) => {
    setPaymentInvoice(inv);
    setPaymentAmount(inv.amount_due);
    setPaymentRef("");
  };

  const handleRecordPayment = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!paymentInvoice || paymentAmount <= 0) return;

    const r = await recordPayment(paymentInvoice.id, paymentAmount, paymentDate, paymentMode, paymentRef || undefined);
    if (r.ok) setPaymentInvoice(null);
  };

  const handlePrint = () => window.print();

  return (
    <div>
      <TopBar title="Invoices & Finance" subtitle={`${invoices.length} total invoices issued`} />
      <div className="p-6">
        {/* KPI Cards */}
        <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-4 gap-4 mb-6">
          <Card className="shadow-sm">
            <CardContent className="p-4 flex items-center gap-4">
              <div className="w-10 h-10 rounded-xl bg-blue-100 flex items-center justify-center flex-shrink-0">
                <IndianRupee className="w-5 h-5 text-blue-600" />
              </div>
              <div>
                <p className="text-xs font-medium text-muted-foreground">Total Invoiced</p>
                <p className="text-xl font-bold">{formatCurrency(totalInvoiced)}</p>
              </div>
            </CardContent>
          </Card>
          <Card className="shadow-sm">
            <CardContent className="p-4 flex items-center gap-4">
              <div className="w-10 h-10 rounded-xl bg-emerald-100 flex items-center justify-center flex-shrink-0">
                <CheckCircle2 className="w-5 h-5 text-emerald-600" />
              </div>
              <div>
                <p className="text-xs font-medium text-muted-foreground">Total Collected</p>
                <p className="text-xl font-bold text-emerald-600">{formatCurrency(totalPaid)}</p>
              </div>
            </CardContent>
          </Card>
          <Card className="shadow-sm">
            <CardContent className="p-4 flex items-center gap-4">
              <div className="w-10 h-10 rounded-xl bg-amber-100 flex items-center justify-center flex-shrink-0">
                <Clock className="w-5 h-5 text-amber-600" />
              </div>
              <div>
                <p className="text-xs font-medium text-muted-foreground">Outstanding Balance</p>
                <p className="text-xl font-bold text-amber-600">{formatCurrency(totalOutstanding)}</p>
              </div>
            </CardContent>
          </Card>
          <Card className={cn("shadow-sm", overdueCount > 0 ? "border-red-200 bg-red-50/50" : "")}>
            <CardContent className="p-4 flex items-center gap-4">
              <div className="w-10 h-10 rounded-xl bg-red-100 flex items-center justify-center flex-shrink-0">
                <AlertCircle className="w-5 h-5 text-red-600" />
              </div>
              <div>
                <p className="text-xs font-medium text-muted-foreground">Overdue Invoices</p>
                <p className="text-xl font-bold text-red-600">{overdueCount}</p>
              </div>
            </CardContent>
          </Card>
        </div>

        {/* Toolbar */}
        <div className="flex flex-col sm:flex-row items-stretch sm:items-center justify-between mb-6 gap-3">
          <div className="flex flex-1 items-center gap-2 max-w-lg">
            <div className="relative flex-1">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
              <Input
                placeholder="Search invoice #, client or project…"
                className="pl-9"
                value={search}
                onChange={(e) => setSearch(e.target.value)}
              />
            </div>

            {/* Status Filter */}
            <select
              value={statusFilter}
              onChange={(e) => setStatusFilter(e.target.value)}
              className="text-xs border border-input rounded-md px-2.5 py-2 bg-background focus:outline-none focus:ring-1 focus:ring-ring"
            >
              <option value="all">All Status</option>
              <option value="paid">Paid</option>
              <option value="issued">Issued / Unpaid</option>
              <option value="partially_paid">Partially Paid</option>
              <option value="overdue">Overdue</option>
            </select>
          </div>

          <Button
            onClick={() => setShowCreateModal(true)}
            className="gap-2 gradient-primary border-0 text-white shadow-sm"
          >
            <Plus className="w-4 h-4" />
            Create Invoice
          </Button>
        </div>

        {/* Invoices Table */}
        <Card className="shadow-sm overflow-hidden">
          <Table>
            <TableHeader>
              <TableRow className="bg-slate-50/70">
                <TableHead>Invoice No.</TableHead>
                <TableHead>Client & Project</TableHead>
                <TableHead>Dates</TableHead>
                <TableHead>Status</TableHead>
                <TableHead className="text-right">Total Amount</TableHead>
                <TableHead className="text-right">Balance Due</TableHead>
                <TableHead className="w-12 text-center">Actions</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {filtered.map((inv) => (
                <TableRow key={inv.id} className="hover:bg-muted/40 transition-colors">
                  <TableCell className="font-semibold text-foreground">
                    <button
                      type="button"
                      onClick={() => setViewInvoice(inv)}
                      className="hover:underline text-primary font-mono text-xs flex items-center gap-1"
                    >
                      <Receipt className="w-3.5 h-3.5" />
                      {inv.invoice_number ?? "Draft"}
                    </button>
                  </TableCell>
                  <TableCell>
                    <p className="text-sm font-medium text-foreground">{inv.client_name}</p>
                    <Link
                      href={`/projects/${inv.project_id}`}
                      className="text-xs text-muted-foreground hover:text-primary flex items-center gap-1"
                    >
                      {inv.project_name} <ArrowUpRight className="w-3 h-3" />
                    </Link>
                  </TableCell>
                  <TableCell>
                    <p className="text-xs text-foreground">Issued: {inv.issue_date ? formatDate(inv.issue_date) : "—"}</p>
                    <p className="text-xs text-muted-foreground">Due: {inv.due_date ? formatDate(inv.due_date) : "—"}</p>
                  </TableCell>
                  <TableCell>
                    <Badge className={cn("text-xs border-0", getStatusColor(inv.status))}>
                      {inv.status.replace("_", " ").toUpperCase()}
                    </Badge>
                  </TableCell>
                  <TableCell className="text-right font-semibold">
                    {formatCurrency(inv.total_amount)}
                  </TableCell>
                  <TableCell className="text-right">
                    {inv.amount_due > 0 ? (
                      <span className="font-bold text-amber-600 text-sm">
                        {formatCurrency(inv.amount_due)}
                      </span>
                    ) : (
                      <span className="text-emerald-600 text-xs font-semibold flex items-center justify-end gap-1">
                        <CheckCircle2 className="w-3.5 h-3.5" /> Paid
                      </span>
                    )}
                  </TableCell>
                  <TableCell className="text-center">
                    <DropdownMenu>
                      <DropdownMenuTrigger className="w-8 h-8 inline-flex items-center justify-center rounded-md hover:bg-muted cursor-pointer border-0 bg-transparent text-slate-600">
                        <MoreHorizontal className="w-4 h-4" />
                      </DropdownMenuTrigger>
                      <DropdownMenuContent align="end">
                        <DropdownMenuItem onClick={() => setViewInvoice(inv)}>
                          <Receipt className="w-3.5 h-3.5 mr-2 text-primary" /> View & Print Invoice
                        </DropdownMenuItem>
                        {inv.amount_due > 0 && (
                          <DropdownMenuItem
                            onClick={() => openPaymentModal(inv)}
                            className="text-emerald-700 font-medium"
                          >
                            <CreditCard className="w-3.5 h-3.5 mr-2 text-emerald-600" /> Record Payment
                          </DropdownMenuItem>
                        )}
                      </DropdownMenuContent>
                    </DropdownMenu>
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
          {filtered.length === 0 && (
            <div className="py-16 text-center text-muted-foreground">
              <Receipt className="w-12 h-12 text-muted-foreground/30 mx-auto mb-2" />
              <p className="text-sm font-semibold text-foreground">No invoices found</p>
              <p className="text-xs mt-0.5">Try clearing the search or filter query.</p>
            </div>
          )}
        </Card>
      </div>

      {/* Create Invoice Dialog */}
      <Dialog open={showCreateModal} onOpenChange={setShowCreateModal}>
        <DialogContent className="max-w-md">
          <DialogHeader>
            <DialogTitle>Create New Tax Invoice</DialogTitle>
            <DialogDescription>
              Issue an invoice for project milestones or custom deliverable phases.
            </DialogDescription>
          </DialogHeader>

          <form onSubmit={handleCreateInvoice} className="space-y-4 py-2">
            <div>
              <label className="text-xs font-semibold text-foreground block mb-1">Select Project *</label>
              <select
                value={selectedProjectId}
                onChange={(e) => setSelectedProjectId(e.target.value)}
                className="w-full text-sm border border-input rounded-md px-3 py-2 bg-background focus:outline-none focus:ring-2 focus:ring-ring"
              >
                {projects.map((p) => (
                  <option key={p.id} value={p.id}>
                    {p.name} ({p.client_name})
                  </option>
                ))}
              </select>
            </div>

            <div>
              <label className="text-xs font-semibold text-foreground block mb-1">Milestone Description *</label>
              <Input
                required
                value={invoiceTitle}
                onChange={(e) => setInvoiceTitle(e.target.value)}
                placeholder="e.g. Carpentry Work 40% Advance"
              />
            </div>

            <div className="grid grid-cols-2 gap-3">
              <div>
                <label className="text-xs font-semibold text-foreground block mb-1">Subtotal (₹) *</label>
                <Input
                  type="number"
                  required
                  value={subtotal}
                  onChange={(e) => setSubtotal(Number(e.target.value))}
                />
              </div>
              <div>
                <label className="text-xs font-semibold text-foreground block mb-1">Due Date *</label>
                <Input
                  type="date"
                  required
                  value={dueDate}
                  onChange={(e) => setDueDate(e.target.value)}
                />
              </div>
            </div>

            <div className="p-3 bg-slate-50 rounded-lg border border-border text-xs space-y-1">
              <div className="flex justify-between">
                <span className="text-muted-foreground">Subtotal:</span>
                <span className="font-semibold">{formatCurrency(subtotal)}</span>
              </div>
              <div className="flex justify-between">
                <span className="text-muted-foreground">GST ({studioSettings.gst_rate}%):</span>
                <span className="font-semibold">{formatCurrency((subtotal * studioSettings.gst_rate) / 100)}</span>
              </div>
              <div className="flex justify-between border-t border-border pt-1 font-bold text-sm text-foreground">
                <span>Total Invoice Value:</span>
                <span>{formatCurrency(subtotal * (1 + studioSettings.gst_rate / 100))}</span>
              </div>
            </div>

            <DialogFooter className="gap-2 sm:gap-0 pt-2">
              <Button type="button" variant="outline" onClick={() => setShowCreateModal(false)}>
                Cancel
              </Button>
              <Button type="submit" className="gradient-primary border-0 text-white">
                Generate Invoice
              </Button>
            </DialogFooter>
          </form>
        </DialogContent>
      </Dialog>

      {/* Record Payment Dialog */}
      {paymentInvoice && (
        <Dialog open={!!paymentInvoice} onOpenChange={(open) => !open && setPaymentInvoice(null)}>
          <DialogContent className="max-w-md">
            <DialogHeader>
              <DialogTitle className="flex items-center gap-2">
                <CreditCard className="w-5 h-5 text-emerald-600" />
                Record Payment for {paymentInvoice.invoice_number}
              </DialogTitle>
              <DialogDescription>
                Client: {paymentInvoice.client_name} · Due: {formatCurrency(paymentInvoice.amount_due)}
              </DialogDescription>
            </DialogHeader>

            <form onSubmit={handleRecordPayment} className="space-y-4 py-2">
              <div>
                <label className="text-xs font-semibold text-foreground block mb-1">Amount Received (₹) *</label>
                <Input
                  type="number"
                  max={paymentInvoice.amount_due}
                  required
                  value={paymentAmount}
                  onChange={(e) => setPaymentAmount(Number(e.target.value))}
                />
              </div>

              <div className="grid grid-cols-2 gap-3">
                <div>
                  <label className="text-xs font-semibold text-foreground block mb-1">Payment Mode *</label>
                  <select
                    value={paymentMode}
                    onChange={(e) => setPaymentMode(e.target.value as PaymentMode)}
                    className="w-full text-sm border border-input rounded-md px-3 py-2 bg-background focus:outline-none focus:ring-2 focus:ring-ring"
                  >
                    {Object.entries(PAYMENT_MODE_LABELS).map(([k, label]) => (
                      <option key={k} value={k}>{label}</option>
                    ))}
                  </select>
                </div>
                <div>
                  <label className="text-xs font-semibold text-foreground block mb-1">Payment Date *</label>
                  <Input
                    type="date"
                    required
                    value={paymentDate}
                    onChange={(e) => setPaymentDate(e.target.value)}
                  />
                </div>
              </div>

              <div>
                <label className="text-xs font-semibold text-foreground block mb-1">Transaction Ref / Cheque No.</label>
                <Input
                  value={paymentRef}
                  onChange={(e) => setPaymentRef(e.target.value)}
                  placeholder="e.g. UTR194820129"
                />
              </div>

              <DialogFooter className="gap-2 sm:gap-0 pt-2">
                <Button type="button" variant="outline" onClick={() => setPaymentInvoice(null)}>
                  Cancel
                </Button>
                <Button type="submit" className="bg-emerald-600 hover:bg-emerald-700 text-white border-0 gap-1.5">
                  <Check className="w-4 h-4" /> Save Receipt
                </Button>
              </DialogFooter>
            </form>
          </DialogContent>
        </Dialog>
      )}

      {/* Invoice PDF / View Dialog */}
      {viewInvoice && (
        <Dialog open={!!viewInvoice} onOpenChange={(open) => !open && setViewInvoice(null)}>
          <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto">
            <div className="p-4 bg-white space-y-6">
              {/* Studio Header */}
              <div className="flex justify-between items-start border-b border-border pb-4">
                <div>
                  <div className="w-8 h-8 rounded-lg gradient-primary flex items-center justify-center text-white font-bold mb-2">
                    <Building2 className="w-4 h-4" />
                  </div>
                  <h2 className="text-lg font-bold text-foreground">{studioSettings.name}</h2>
                  <p className="text-xs text-muted-foreground">{studioSettings.address}</p>
                  <p className="text-xs text-muted-foreground">GSTIN: {studioSettings.gstin}</p>
                  <p className="text-xs text-muted-foreground">PAN: {studioSettings.pan}</p>
                </div>
                <div className="text-right">
                  <span className="text-xs font-bold uppercase tracking-wider text-muted-foreground block">
                    TAX INVOICE
                  </span>
                  <p className="text-lg font-bold text-primary font-mono">{viewInvoice.invoice_number ?? "Draft"}</p>
                  <p className="text-xs text-muted-foreground">Issued: {viewInvoice.issue_date ? formatDate(viewInvoice.issue_date) : "—"}</p>
                  <p className="text-xs text-muted-foreground">Due: {viewInvoice.due_date ? formatDate(viewInvoice.due_date) : "—"}</p>

                  {viewInvoice.status === "paid" && (
                    <div className="mt-2 inline-block border-2 border-emerald-500 text-emerald-600 font-extrabold text-xs px-2.5 py-0.5 rounded tracking-widest uppercase rotate-[-6deg]">
                      PAID
                    </div>
                  )}
                </div>
              </div>

              {/* Billed To & Project */}
              <div className="bg-slate-50 p-3 rounded-lg border border-border text-xs grid grid-cols-2 gap-4">
                <div>
                  <span className="text-muted-foreground block font-medium mb-0.5">Billed To:</span>
                  <p className="font-bold text-sm text-foreground">{viewInvoice.client_name}</p>
                </div>
                <div>
                  <span className="text-muted-foreground block font-medium mb-0.5">Project:</span>
                  <p className="font-semibold text-foreground">{viewInvoice.project_name}</p>
                </div>
              </div>

              {/* Line Items */}
              <table className="w-full text-xs">
                <thead>
                  <tr className="border-b border-border text-muted-foreground text-left uppercase">
                    <th className="py-2">Description</th>
                    <th className="py-2 text-center">Qty</th>
                    <th className="py-2 text-right">Rate</th>
                    <th className="py-2 text-right">Amount (₹)</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-border">
                  {viewInvoice.items && viewInvoice.items.length > 0 ? (
                    viewInvoice.items.map((it) => (
                      <tr key={it.id}>
                        <td className="py-3 font-medium text-foreground">{it.description}</td>
                        <td className="py-3 text-center text-muted-foreground">{it.quantity}</td>
                        <td className="py-3 text-right text-muted-foreground">{formatCurrency(it.unit_rate || 0)}</td>
                        <td className="py-3 text-right font-semibold">{formatCurrency(it.amount || 0)}</td>
                      </tr>
                    ))
                  ) : (
                    <tr>
                      <td className="py-3 font-medium text-foreground">Project Milestone Payment</td>
                      <td className="py-3 text-center text-muted-foreground">1</td>
                      <td className="py-3 text-right text-muted-foreground">{formatCurrency(viewInvoice.subtotal)}</td>
                      <td className="py-3 text-right font-semibold">{formatCurrency(viewInvoice.subtotal)}</td>
                    </tr>
                  )}
                </tbody>
              </table>

              {/* Totals */}
              <div className="border-t border-border pt-3 space-y-1.5 text-xs">
                <div className="flex justify-between text-muted-foreground">
                  <span>Subtotal:</span>
                  <span>{formatCurrency(viewInvoice.subtotal)}</span>
                </div>
                <div className="flex justify-between text-muted-foreground">
                  <span>GST ({studioSettings.gst_rate}%):</span>
                  <span>{formatCurrency(viewInvoice.gst_amount || 0)}</span>
                </div>
                <div className="flex justify-between font-bold text-base text-foreground pt-2 border-t border-border">
                  <span>Total Amount:</span>
                  <span>{formatCurrency(viewInvoice.total_amount)}</span>
                </div>
                <div className="flex justify-between text-emerald-600 font-medium">
                  <span>Amount Paid:</span>
                  <span>{formatCurrency(viewInvoice.amount_paid)}</span>
                </div>
                <div className="flex justify-between font-bold text-amber-600">
                  <span>Balance Due:</span>
                  <span>{formatCurrency(viewInvoice.amount_due)}</span>
                </div>
              </div>

              {/* Bank Details */}
              <div className="p-3 bg-slate-50 rounded-lg border border-border text-xs text-muted-foreground">
                <p className="font-semibold text-foreground mb-1">Bank Payment Instructions:</p>
                <p>Beneficiary: {studioSettings.bank_details.account_name}</p>
                <p>Account: {studioSettings.bank_details.account_number} | IFSC: {studioSettings.bank_details.ifsc_code} | Bank: {studioSettings.bank_details.bank_name}</p>
                <p>UPI ID: {studioSettings.bank_details.upi_id}</p>
              </div>
            </div>

            <DialogFooter className="gap-2 sm:gap-0">
              <Button variant="outline" onClick={() => setViewInvoice(null)}>
                Close
              </Button>
              <Button onClick={handlePrint} className="gradient-primary border-0 text-white gap-1.5">
                <Printer className="w-4 h-4" /> Print / Save PDF
              </Button>
            </DialogFooter>
          </DialogContent>
        </Dialog>
      )}
    </div>
  );
}

"use client";

import { useState } from "react";
import Link from "next/link";
import { TopBar } from "@/components/layout/AppSidebar";
import { Card, CardContent } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import {
  Bell, CheckCheck, IndianRupee, AlertCircle, FileText, CheckSquare,
  MessageSquare, Sparkles, ExternalLink, Clock
} from "lucide-react";
import { useAppStore } from "@/lib/store";
import { formatRelativeTime, cn } from "@/lib/utils";

export default function NotificationsPage() {
  const { notifications, markNotificationRead, markAllNotificationsRead } = useAppStore();

  const [activeFilter, setActiveFilter] = useState<string>("all");

  const unreadCount = notifications.filter((n) => !n.is_read).length;

  const filtered = notifications.filter((n) => {
    if (activeFilter === "all") return true;
    if (activeFilter === "unread") return !n.is_read;
    if (activeFilter === "payment") return n.type === "payment" || n.title.toLowerCase().includes("payment");
    if (activeFilter === "snag") return n.type === "snag" || n.title.toLowerCase().includes("snag");
    if (activeFilter === "boq") return n.type === "boq" || n.title.toLowerCase().includes("boq");
    if (activeFilter === "task") return n.type === "task" || n.title.toLowerCase().includes("task");
    return true;
  });

  const getNotifIcon = (type: string, title: string) => {
    const t = (type + " " + title).toLowerCase();
    if (t.includes("payment") || t.includes("invoice")) {
      return <IndianRupee className="w-4 h-4 text-emerald-600" />;
    }
    if (t.includes("snag") || t.includes("defect")) {
      return <AlertCircle className="w-4 h-4 text-amber-600" />;
    }
    if (t.includes("boq") || t.includes("approved")) {
      return <FileText className="w-4 h-4 text-primary" />;
    }
    if (t.includes("task")) {
      return <CheckSquare className="w-4 h-4 text-blue-600" />;
    }
    if (t.includes("message")) {
      return <MessageSquare className="w-4 h-4 text-primary" />;
    }
    return <Bell className="w-4 h-4 text-slate-600" />;
  };

  return (
    <div>
      <TopBar title="Notifications" subtitle={`${unreadCount} unread alerts requiring attention`} />
      <div className="p-6 space-y-4">
        {/* Toolbar */}
        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3">
          <div className="flex flex-wrap gap-1.5 bg-card border border-border p-1 rounded-lg">
            {(
              [
                { key: "all", label: `All (${notifications.length})` },
                { key: "unread", label: `Unread (${unreadCount})` },
                { key: "payment", label: "Payments" },
                { key: "snag", label: "Snags" },
                { key: "boq", label: "BOQ" },
                { key: "task", label: "Tasks" },
              ] as const
            ).map((tab) => (
              <button
                key={tab.key}
                onClick={() => setActiveFilter(tab.key)}
                className={cn(
                  "px-3 py-1.5 rounded-md text-xs font-medium transition-colors",
                  activeFilter === tab.key
                    ? "bg-slate-900 text-white"
                    : "text-muted-foreground hover:bg-slate-100 hover:text-foreground"
                )}
              >
                {tab.label}
              </button>
            ))}
          </div>

          {unreadCount > 0 && (
            <Button
              variant="outline"
              size="sm"
              onClick={markAllNotificationsRead}
              className="gap-1.5 text-xs self-start sm:self-auto"
            >
              <CheckCheck className="w-3.5 h-3.5 text-primary" />
              Mark all as read
            </Button>
          )}
        </div>

        {/* Notification Feed */}
        <Card className="shadow-sm overflow-hidden">
          <CardContent className="p-0 divide-y divide-border">
            {filtered.map((notif) => (
              <div
                key={notif.id}
                onClick={() => markNotificationRead(notif.id)}
                className={cn(
                  "p-4 flex items-start gap-4 transition-colors cursor-pointer hover:bg-slate-50/80",
                  notif.is_read ? "bg-white" : "bg-accent/25"
                )}
              >
                <div
                  className={cn(
                    "w-9 h-9 rounded-xl flex items-center justify-center flex-shrink-0 mt-0.5",
                    notif.is_read ? "bg-slate-100" : "bg-primary/10"
                  )}
                >
                  {getNotifIcon(notif.type, notif.title)}
                </div>

                <div className="flex-1 min-w-0">
                  <div className="flex items-center justify-between gap-2">
                    <h4
                      className={cn(
                        "text-sm",
                        notif.is_read
                          ? "text-slate-800 font-medium"
                          : "text-foreground font-bold"
                      )}
                    >
                      {notif.title}
                    </h4>
                    <span className="text-[11px] text-muted-foreground whitespace-nowrap flex items-center gap-1">
                      <Clock className="w-3 h-3" /> {formatRelativeTime(notif.created_at)}
                    </span>
                  </div>
                  <p className="text-xs text-muted-foreground mt-0.5 leading-relaxed">
                    {notif.body}
                  </p>
                </div>

                {!notif.is_read && (
                  <div className="w-2 h-2 rounded-full bg-primary self-center flex-shrink-0" />
                )}
              </div>
            ))}

            {filtered.length === 0 && (
              <div className="py-16 text-center text-muted-foreground">
                <Bell className="w-10 h-10 opacity-30 mx-auto mb-2" />
                <p className="text-sm font-semibold text-foreground">No notifications in this filter</p>
                <p className="text-xs mt-0.5">You&apos;re all caught up!</p>
              </div>
            )}
          </CardContent>
        </Card>
      </div>
    </div>
  );
}

"use client";

import { useState } from "react";
import { TopBar } from "@/components/layout/AppSidebar";
import { Card, CardContent } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import {
  Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription, DialogFooter,
} from "@/components/ui/dialog";
import {
  CheckSquare, Plus, Clock, AlertCircle, Trash2, Calendar, CheckCircle2,
  FolderKanban, User, Filter
} from "lucide-react";
import { useAppStore } from "@/lib/store";
import { formatShortDate, getPriorityColor, isOverdue, cn } from "@/lib/utils";
import { Task, TaskPriority, TaskStatus } from "@/types";
import { AssigneeSelect } from "@/components/team/AssigneeSelect";

export default function TasksPage() {
  const { tasks, projects, addTask, updateTaskStatus, deleteTask } = useAppStore();

  const [activeTab, setActiveTab] = useState<"all" | "todo" | "in_progress" | "done" | "overdue">("all");
  const [selectedProjectId, setSelectedProjectId] = useState<string>("all");
  const [selectedPriority, setSelectedPriority] = useState<string>("all");
  const [search, setSearch] = useState("");

  // Add Task Modal State
  const [showAddModal, setShowAddModal] = useState(false);
  const [taskTitle, setTaskTitle] = useState("");
  const [taskProject, setTaskProject] = useState(projects[0]?.id || "");
  const [taskAssignee, setTaskAssignee] = useState("");
  const [taskPriority, setTaskPriority] = useState<TaskPriority>("medium");
  const [taskDueDate, setTaskDueDate] = useState("");

  const filteredTasks = tasks.filter((t) => {
    // Project filter
    if (selectedProjectId !== "all" && t.project_id !== selectedProjectId) return false;
    // Priority filter
    if (selectedPriority !== "all" && t.priority !== selectedPriority) return false;
    // Search
    if (search && !t.title.toLowerCase().includes(search.toLowerCase())) return false;
    // Tab
    if (activeTab === "all") return true;
    if (activeTab === "todo") return t.status === "todo";
    if (activeTab === "in_progress") return t.status === "in_progress";
    if (activeTab === "done") return t.status === "done";
    if (activeTab === "overdue") return !!t.due_date && isOverdue(t.due_date) && t.status !== "done";
    return true;
  });

  const todoCount = tasks.filter((t) => t.status === "todo").length;
  const inProgressCount = tasks.filter((t) => t.status === "in_progress").length;
  const overdueCount = tasks.filter((t) => !!t.due_date && isOverdue(t.due_date) && t.status !== "done").length;
  const doneCount = tasks.filter((t) => t.status === "done").length;

  const handleCreateTask = (e: React.FormEvent) => {
    e.preventDefault();
    if (!taskTitle.trim()) return;

    addTask({
      project_id: taskProject,
      title: taskTitle.trim(),
      assigned_to: taskAssignee || undefined,
      priority: taskPriority,
      due_date: taskDueDate || undefined,
      is_internal: true,
    });

    setTaskTitle("");
    setTaskDueDate("");
    setTaskAssignee("");
    setShowAddModal(false);
  };

  const toggleTaskDone = (task: Task) => {
    const newStatus: TaskStatus = task.status === "done" ? "todo" : "done";
    updateTaskStatus(task.id, newStatus);
  };

  return (
    <div>
      <TopBar title="Task Management" subtitle="Daily standup, site checklists, and team assignments" />
      <div className="p-6">
        {/* KPI Summary Cards */}
        <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mb-6">
          <Card className="shadow-sm">
            <CardContent className="p-4">
              <p className="text-xs text-muted-foreground font-medium">To Do</p>
              <p className="text-2xl font-bold text-foreground mt-1">{todoCount}</p>
            </CardContent>
          </Card>
          <Card className="shadow-sm">
            <CardContent className="p-4">
              <p className="text-xs text-muted-foreground font-medium">In Progress</p>
              <p className="text-2xl font-bold text-primary mt-1">{inProgressCount}</p>
            </CardContent>
          </Card>
          <Card className={cn("shadow-sm", overdueCount > 0 ? "border-red-200 bg-red-50/50" : "")}>
            <CardContent className="p-4">
              <p className="text-xs text-muted-foreground font-medium">Overdue</p>
              <p className="text-2xl font-bold text-red-600 mt-1">{overdueCount}</p>
            </CardContent>
          </Card>
          <Card className="shadow-sm">
            <CardContent className="p-4">
              <p className="text-xs text-muted-foreground font-medium">Completed</p>
              <p className="text-2xl font-bold text-emerald-600 mt-1">{doneCount}</p>
            </CardContent>
          </Card>
        </div>

        {/* Toolbar & Filters */}
        <div className="flex flex-col md:flex-row items-stretch md:items-center justify-between gap-3 mb-6">
          <div className="flex flex-wrap items-center gap-2">
            {/* Status Tabs */}
            <div className="flex rounded-lg border border-border bg-card p-1">
              {(
                [
                  { key: "all", label: "All" },
                  { key: "todo", label: "To Do" },
                  { key: "in_progress", label: "In Progress" },
                  { key: "overdue", label: `Overdue (${overdueCount})` },
                  { key: "done", label: "Done" },
                ] as const
              ).map((tab) => (
                <button
                  key={tab.key}
                  onClick={() => setActiveTab(tab.key)}
                  className={cn(
                    "px-3 py-1.5 text-xs rounded-md capitalize font-medium transition-colors",
                    activeTab === tab.key
                      ? "bg-slate-900 text-white shadow-xs"
                      : "hover:bg-muted text-muted-foreground"
                  )}
                >
                  {tab.label}
                </button>
              ))}
            </div>

            {/* Project Filter */}
            <select
              value={selectedProjectId}
              onChange={(e) => setSelectedProjectId(e.target.value)}
              className="text-xs border border-input rounded-md px-2.5 py-2 bg-background focus:outline-none focus:ring-1 focus:ring-ring"
            >
              <option value="all">All Projects</option>
              {projects.map((p) => (
                <option key={p.id} value={p.id}>
                  {p.name}
                </option>
              ))}
            </select>

            {/* Priority Filter */}
            <select
              value={selectedPriority}
              onChange={(e) => setSelectedPriority(e.target.value)}
              className="text-xs border border-input rounded-md px-2.5 py-2 bg-background focus:outline-none focus:ring-1 focus:ring-ring"
            >
              <option value="all">All Priorities</option>
              <option value="low">Low</option>
              <option value="medium">Medium</option>
              <option value="high">High</option>
              <option value="urgent">Urgent</option>
            </select>
          </div>

          <Button
            onClick={() => setShowAddModal(true)}
            className="gap-2 gradient-primary border-0 text-white shadow-sm"
          >
            <Plus className="w-4 h-4" /> Add Task
          </Button>
        </div>

        {/* Task List */}
        <div className="space-y-2.5">
          {filteredTasks.map((task) => {
            const isDone = task.status === "done";
            const taskIsOverdue = !!task.due_date && isOverdue(task.due_date) && !isDone;

            return (
              <Card
                key={task.id}
                className={cn(
                  "shadow-xs hover:border-primary/20 transition-all",
                  isDone ? "bg-slate-50/60 opacity-80" : "bg-white"
                )}
              >
                <CardContent className="p-3.5 flex items-center justify-between gap-3">
                  <div className="flex items-center gap-3.5 flex-1 min-w-0">
                    <button
                      type="button"
                      onClick={() => toggleTaskDone(task)}
                      className={cn(
                        "w-5 h-5 rounded-md border flex items-center justify-center transition-colors cursor-pointer",
                        isDone
                          ? "bg-emerald-600 border-emerald-600 text-white"
                          : "border-slate-300 hover:border-indigo-600 text-transparent"
                      )}
                    >
                      <CheckCircle2 className="w-3.5 h-3.5" />
                    </button>

                    <div className="min-w-0 flex-1">
                      <p
                        className={cn(
                          "text-sm font-medium truncate",
                          isDone ? "line-through text-muted-foreground" : "text-foreground"
                        )}
                      >
                        {task.title}
                      </p>
                      <div className="flex items-center gap-3 text-xs text-muted-foreground mt-0.5">
                        <span className="flex items-center gap-1 truncate max-w-[200px]">
                          <FolderKanban className="w-3 h-3" /> {task.project_name}
                        </span>
                        {task.assigned_to && (
                          <span className="hidden sm:flex items-center gap-1">
                            <User className="w-3 h-3" /> {task.assigned_to}
                          </span>
                        )}
                      </div>
                    </div>
                  </div>

                  <div className="flex items-center gap-3 flex-shrink-0">
                    <Badge className={cn("border-0 text-[10px] capitalize", getPriorityColor(task.priority))}>
                      {task.priority}
                    </Badge>

                    {task.due_date && (
                      <span
                        className={cn(
                          "text-xs flex items-center gap-1 font-medium",
                          taskIsOverdue ? "text-red-500 font-semibold" : "text-muted-foreground"
                        )}
                      >
                        {taskIsOverdue ? (
                          <AlertCircle className="w-3.5 h-3.5 text-red-500" />
                        ) : (
                          <Clock className="w-3.5 h-3.5" />
                        )}
                        {formatShortDate(task.due_date)}
                      </span>
                    )}

                    <button
                      type="button"
                      onClick={() => deleteTask(task.id)}
                      className="p-1 rounded text-slate-400 hover:text-red-600 hover:bg-red-50 transition-colors"
                      title="Delete task"
                    >
                      <Trash2 className="w-3.5 h-3.5" />
                    </button>
                  </div>
                </CardContent>
              </Card>
            );
          })}

          {filteredTasks.length === 0 && (
            <div className="py-16 text-center text-muted-foreground bg-white rounded-xl border border-border">
              <CheckSquare className="w-10 h-10 opacity-30 mx-auto mb-2" />
              <p className="text-sm font-semibold text-foreground">No tasks in this view</p>
              <p className="text-xs mt-0.5">All clear or no tasks match your filters.</p>
            </div>
          )}
        </div>
      </div>

      {/* Add Task Modal */}
      <Dialog open={showAddModal} onOpenChange={setShowAddModal}>
        <DialogContent className="max-w-md">
          <DialogHeader>
            <DialogTitle>Add New Task</DialogTitle>
            <DialogDescription>
              Assign deliverables, site inspections, and follow-ups.
            </DialogDescription>
          </DialogHeader>

          <form onSubmit={handleCreateTask} className="space-y-4 py-2">
            <div>
              <label className="text-xs font-semibold text-foreground block mb-1">Task Title *</label>
              <Input
                required
                value={taskTitle}
                onChange={(e) => setTaskTitle(e.target.value)}
                placeholder="e.g. Inspect plumbing rough-ins with site contractor"
              />
            </div>

            <div>
              <label className="text-xs font-semibold text-foreground block mb-1">Associated Project *</label>
              <select
                value={taskProject}
                onChange={(e) => setTaskProject(e.target.value)}
                className="w-full text-sm border border-input rounded-md px-3 py-2 bg-background focus:outline-none focus:ring-2 focus:ring-ring"
              >
                {projects.map((p) => (
                  <option key={p.id} value={p.id}>
                    {p.name}
                  </option>
                ))}
              </select>
            </div>

            <div className="grid grid-cols-2 gap-3">
              <div>
                <label className="text-xs font-semibold text-foreground block mb-1">Assignee</label>
                <AssigneeSelect
                  value={taskAssignee}
                  onChange={setTaskAssignee}
                />
              </div>
              <div>
                <label className="text-xs font-semibold text-foreground block mb-1">Due Date *</label>
                <Input
                  type="date"
                  required
                  value={taskDueDate}
                  onChange={(e) => setTaskDueDate(e.target.value)}
                />
              </div>
            </div>

            <div>
              <label className="text-xs font-semibold text-foreground block mb-1">Priority</label>
              <div className="grid grid-cols-4 gap-2">
                {(["low", "medium", "high", "urgent"] as const).map((p) => (
                  <button
                    type="button"
                    key={p}
                    onClick={() => setTaskPriority(p as TaskPriority)}
                    className={cn(
                      "text-xs py-1.5 rounded-md border text-center capitalize transition-colors font-medium",
                      taskPriority === p
                        ? "border-primary bg-primary text-white"
                        : "border-border hover:bg-slate-50 text-foreground"
                    )}
                  >
                    {p}
                  </button>
                ))}
              </div>
            </div>

            <DialogFooter className="gap-2 sm:gap-0 pt-2">
              <Button type="button" variant="outline" onClick={() => setShowAddModal(false)}>
                Cancel
              </Button>
              <Button type="submit" className="gradient-primary border-0 text-white">
                Create Task
              </Button>
            </DialogFooter>
          </form>
        </DialogContent>
      </Dialog>
    </div>
  );
}

"use client";

import { useState } from "react";
import Link from "next/link";
import { useRouter } from "next/navigation";
import { Card, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import { Progress } from "@/components/ui/progress";
import {
  Building2, ArrowRight, ArrowLeft, Check, Sparkles, Home, Layers,
  CheckCircle2, Compass, Palette, IndianRupee, Heart, ShieldCheck
} from "lucide-react";
import { submitOnboarding } from "@/app/actions/onboarding";

export default function OnboardingPage() {
  const router = useRouter();
  
  const [step, setStep] = useState(1);
  const totalSteps = 4;

  // Form State
  const [fullName, setFullName] = useState("");
  const [phone, setPhone] = useState("");
  const [email, setEmail] = useState("");
  const [address, setAddress] = useState("");

  const [propertyType, setPropertyType] = useState("Apartment (3BHK)");
  const [carpetArea, setCarpetArea] = useState(1650);
  const [selectedRooms, setSelectedRooms] = useState<string[]>([
    "Living & Dining",
    "Master Bedroom",
    "Modular Kitchen",
  ]);

  const [selectedStyle, setSelectedStyle] = useState("Japandi");
  const [budgetTier, setBudgetTier] = useState("Premium (₹15L - ₹25L)");

  // Submitted project portal slug
  const [submitted, setSubmitted] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);

  const toggleRoom = (room: string) => {
    setSelectedRooms((prev) =>
      prev.includes(room) ? prev.filter((r) => r !== room) : [...prev, room]
    );
  };

  const STYLES = [
    {
      id: "Japandi",
      name: "Japandi",
      desc: "Warm minimalism, light oak, organic textures, functional calm.",
      image: "https://images.unsplash.com/photo-1598928506311-c55ded91a20c?w=600&auto=format&fit=crop&q=60",
    },
    {
      id: "Contemporary",
      name: "Modern Contemporary",
      desc: "Clean geometry, subtle metallic accents, fluted panels, layered lighting.",
      image: "https://images.unsplash.com/photo-1618221195710-dd6b41faaea6?w=600&auto=format&fit=crop&q=60",
    },
    {
      id: "NeoClassical",
      name: "Neo-Classical Luxury",
      desc: "Mouldings, wainscoting, marble inlays, rich brass trims, European elegance.",
      image: "https://images.unsplash.com/photo-1600210492486-724fe5c67fb0?w=600&auto=format&fit=crop&q=60",
    },
    {
      id: "Minimalist",
      name: "Warm Minimalist",
      desc: "Seamless joinery, concealed storage, neutral palettes, clutter-free.",
      image: "https://images.unsplash.com/photo-1586023492125-27b2c045efd7?w=600&auto=format&fit=crop&q=60",
    },
  ];

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const budgetEstimate = budgetTier.includes("25L") ? 2200000 : budgetTier.includes("15L") ? 1400000 : undefined;
    submitOnboarding({
      full_name: fullName, phone, email, address, property_type: propertyType, area_sqft: carpetArea,
      budget_label: budgetTier, budget_estimate: budgetEstimate, style: selectedStyle, rooms: selectedRooms,
    }).then((r) => {
      if (r.ok) {
        setSubmitted(r.reference);
        setStep(5);
      } else {
        setError(r.error);
      }
    });
  };

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col justify-between">
      {/* Header */}
      <header className="border-b border-border bg-white px-6 py-4">
        <div className="max-w-4xl mx-auto flex items-center justify-between">
          <div className="flex items-center gap-2.5">
            <div className="w-9 h-9 rounded-xl gradient-primary flex items-center justify-center text-white shadow-sm">
              <Building2 className="w-5 h-5" />
            </div>
            <div>
              <p className="font-bold text-foreground text-sm">our studio</p>
              <p className="text-[10px] text-muted-foreground uppercase tracking-wider">Client Design Intake</p>
            </div>
          </div>
          <Link href="/dashboard" className="text-xs text-muted-foreground hover:text-primary">
            Staff Portal →
          </Link>
        </div>
      </header>

      {/* Main Container */}
      <main className="max-w-2xl mx-auto w-full px-4 py-8 flex-1">
        {step <= 4 && (
          <div className="mb-6 space-y-2">
            <div className="flex justify-between text-xs text-muted-foreground">
              <span>Step {step} of {totalSteps}</span>
              <span className="font-medium text-foreground">
                {step === 1 && "Personal & Property Details"}
                {step === 2 && "Scope & Rooms"}
                {step === 3 && "Design Aesthetics"}
                {step === 4 && "Budget & Handover Timeline"}
              </span>
            </div>
            <Progress value={(step / totalSteps) * 100} className="h-1.5" />
          </div>
        )}

        {/* STEP 1 */}
        {step === 1 && (
          <Card className="shadow-sm border border-border">
            <CardContent className="p-6 space-y-5">
              <div>
                <h2 className="text-xl font-bold text-foreground">Tell us about you & your home</h2>
                <p className="text-xs text-muted-foreground mt-1">
                  We&apos;ll customize your interior design consultation based on these details.
                </p>
              </div>

              <div className="space-y-4">
                <div>
                  <label className="text-xs font-semibold text-foreground block mb-1">Your Full Name *</label>
                  <Input
                    required
                    value={fullName}
                    onChange={(e) => setFullName(e.target.value)}
                    placeholder="e.g. Rohini & Siddharth Roy"
                  />
                </div>

                <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                  <div>
                    <label className="text-xs font-semibold text-foreground block mb-1">WhatsApp / Phone *</label>
                    <Input
                      required
                      value={phone}
                      onChange={(e) => setPhone(e.target.value)}
                      placeholder="+91 98765 00000"
                    />
                  </div>
                  <div>
                    <label className="text-xs font-semibold text-foreground block mb-1">Email Address</label>
                    <Input
                      type="email"
                      value={email}
                      onChange={(e) => setEmail(e.target.value)}
                      placeholder="name@example.com"
                    />
                  </div>
                </div>

                <div>
                  <label className="text-xs font-semibold text-foreground block mb-1">Property Address / Community *</label>
                  <Input
                    required
                    value={address}
                    onChange={(e) => setAddress(e.target.value)}
                    placeholder="e.g. Tower 3, Flat 1204, Prestige Lakeside Habitat, Varthur"
                  />
                </div>
              </div>

              <div className="flex justify-end pt-4">
                <Button
                  disabled={!fullName.trim() || !phone.trim() || !address.trim()}
                  onClick={() => setStep(2)}
                  className="gradient-primary border-0 text-white gap-2"
                >
                  Continue to Scope <ArrowRight className="w-4 h-4" />
                </Button>
              </div>
            </CardContent>
          </Card>
        )}

        {/* STEP 2 */}
        {step === 2 && (
          <Card className="shadow-sm border border-border">
            <CardContent className="p-6 space-y-5">
              <div>
                <h2 className="text-xl font-bold text-foreground">Property Specifications & Scope</h2>
                <p className="text-xs text-muted-foreground mt-1">
                  Select which rooms require design, carpentry, and styling.
                </p>
              </div>

              <div className="space-y-4">
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                  <div>
                    <label className="text-xs font-semibold text-foreground block mb-1">Property Type</label>
                    <select
                      value={propertyType}
                      onChange={(e) => setPropertyType(e.target.value)}
                      className="w-full text-sm border border-input rounded-md px-3 py-2 bg-background focus:outline-none focus:ring-1 focus:ring-ring"
                    >
                      <option value="Apartment (2BHK)">Apartment (2BHK)</option>
                      <option value="Apartment (3BHK)">Apartment (3BHK)</option>
                      <option value="Apartment (4BHK / Penthouse)">Apartment (4BHK / Penthouse)</option>
                      <option value="Independent Villa">Independent Villa</option>
                      <option value="Commercial / Boutique Office">Commercial / Boutique Office</option>
                    </select>
                  </div>
                  <div>
                    <label className="text-xs font-semibold text-foreground block mb-1">Carpet Area (sqft)</label>
                    <Input
                      type="number"
                      value={carpetArea}
                      onChange={(e) => setCarpetArea(Number(e.target.value))}
                    />
                  </div>
                </div>

                <div>
                  <label className="text-xs font-semibold text-foreground block mb-2">
                    Spaces in Scope (Click to toggle)
                  </label>
                  <div className="grid grid-cols-2 sm:grid-cols-3 gap-2">
                    {[
                      "Living & Dining",
                      "Master Bedroom",
                      "Kids / Guest Bedroom",
                      "Modular Kitchen",
                      "Foyer & Entryway",
                      "Balcony / Deck",
                      "Pooja Room",
                      "Home Office / Study",
                      "Bathrooms & Vanity",
                    ].map((room) => {
                      const isSelected = selectedRooms.includes(room);
                      return (
                        <button
                          key={room}
                          type="button"
                          onClick={() => toggleRoom(room)}
                          className={`p-2.5 rounded-lg border text-xs font-medium text-left transition-all ${
                            isSelected
                              ? "border-indigo-600 bg-accent/80 text-indigo-900 shadow-xs"
                              : "border-border hover:bg-slate-50 text-slate-700"
                          }`}
                        >
                          <div className="flex items-center justify-between">
                            <span>{room}</span>
                            {isSelected && <Check className="w-3.5 h-3.5 text-primary" />}
                          </div>
                        </button>
                      );
                    })}
                  </div>
                </div>
              </div>

              <div className="flex justify-between pt-4 border-t border-border">
                <Button variant="outline" onClick={() => setStep(1)} className="gap-1.5">
                  <ArrowLeft className="w-4 h-4" /> Back
                </Button>
                <Button onClick={() => setStep(3)} className="gradient-primary border-0 text-white gap-2">
                  Style Quiz <ArrowRight className="w-4 h-4" />
                </Button>
              </div>
            </CardContent>
          </Card>
        )}

        {/* STEP 3 */}
        {step === 3 && (
          <Card className="shadow-sm border border-border">
            <CardContent className="p-6 space-y-5">
              <div>
                <h2 className="text-xl font-bold text-foreground">Select Your Aesthetic Vibe</h2>
                <p className="text-xs text-muted-foreground mt-1">
                  Which design aesthetic resonates best with your envisioned lifestyle?
                </p>
              </div>

              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                {STYLES.map((st) => {
                  const isSelected = selectedStyle === st.id;
                  return (
                    <div
                      key={st.id}
                      onClick={() => setSelectedStyle(st.id)}
                      className={`overflow-hidden rounded-xl border-2 cursor-pointer transition-all ${
                        isSelected
                          ? "border-indigo-600 shadow-md ring-2 ring-indigo-200"
                          : "border-border hover:border-slate-300"
                      }`}
                    >
                      <div className="h-32 bg-slate-900 overflow-hidden relative">
                        <img
                          src={st.image}
                          alt={st.name}
                          className="w-full h-full object-cover"
                        />
                        {isSelected && (
                          <div className="absolute top-2 right-2 bg-primary text-white p-1 rounded-full">
                            <Check className="w-3.5 h-3.5" />
                          </div>
                        )}
                      </div>
                      <div className="p-3 bg-white">
                        <p className="font-bold text-sm text-foreground">{st.name}</p>
                        <p className="text-xs text-muted-foreground mt-0.5 leading-snug">{st.desc}</p>
                      </div>
                    </div>
                  );
                })}
              </div>

              <div className="flex justify-between pt-4 border-t border-border">
                <Button variant="outline" onClick={() => setStep(2)} className="gap-1.5">
                  <ArrowLeft className="w-4 h-4" /> Back
                </Button>
                <Button onClick={() => setStep(4)} className="gradient-primary border-0 text-white gap-2">
                  Budget & Timeline <ArrowRight className="w-4 h-4" />
                </Button>
              </div>
            </CardContent>
          </Card>
        )}

        {/* STEP 4 */}
        {step === 4 && (
          <Card className="shadow-sm border border-border">
            <CardContent className="p-6 space-y-5">
              <div>
                <h2 className="text-xl font-bold text-foreground">Target Budget & Final Review</h2>
                <p className="text-xs text-muted-foreground mt-1">
                  This helps our team curate matching materials, hardware, and finishes.
                </p>
              </div>

              <div className="space-y-4">
                <div>
                  <label className="text-xs font-semibold text-foreground block mb-2">Target Budget Tier</label>
                  <div className="grid grid-cols-1 sm:grid-cols-3 gap-2.5">
                    {[
                      { tier: "Value (₹8L - ₹15L)", desc: "Commercial ply + laminates, essential storage" },
                      { tier: "Premium (₹15L - ₹25L)", desc: "Marine ply, acrylic/PU finishes, profiles, quartz" },
                      { tier: "Luxury (₹25L+)", desc: "Veneers, Italian marble, smart automation, custom brass" },
                    ].map((b) => (
                      <button
                        key={b.tier}
                        type="button"
                        onClick={() => setBudgetTier(b.tier)}
                        className={`p-3 rounded-xl border text-left transition-all ${
                          budgetTier === b.tier
                            ? "border-indigo-600 bg-accent/70 text-indigo-900"
                            : "border-border hover:bg-slate-50 text-slate-700"
                        }`}
                      >
                        <p className="font-bold text-xs">{b.tier}</p>
                        <p className="text-[11px] text-muted-foreground mt-1 leading-snug">{b.desc}</p>
                      </button>
                    ))}
                  </div>
                </div>

                <div className="p-4 bg-slate-50 rounded-xl border border-border text-xs space-y-1.5">
                  <p className="font-bold text-foreground">Intake Summary</p>
                  <p className="text-muted-foreground">Client: <span className="font-semibold text-foreground">{fullName}</span> ({phone})</p>
                  <p className="text-muted-foreground">Location: <span className="font-semibold text-foreground">{address}</span></p>
                  <p className="text-muted-foreground">Scope: <span className="font-semibold text-foreground">{selectedRooms.join(", ")}</span> ({carpetArea} sqft)</p>
                  <p className="text-muted-foreground">Aesthetic: <span className="font-semibold text-foreground">{selectedStyle}</span></p>
                </div>
              </div>

              <div className="flex justify-between pt-4 border-t border-border">
                <Button variant="outline" onClick={() => setStep(3)} className="gap-1.5">
                  <ArrowLeft className="w-4 h-4" /> Back
                </Button>
                {error && <p role="alert" className="text-sm text-destructive mb-2">{error}</p>}
                <Button onClick={handleSubmit} className="gradient-primary border-0 text-white gap-2 shadow-sm">
                  <Sparkles className="w-4 h-4" /> Submit & Create Client Portal
                </Button>
              </div>
            </CardContent>
          </Card>
        )}

        {/* STEP 5: Success & Portal Created */}
        {submitted && (
          <Card className="shadow-lg border-emerald-200 bg-white text-center p-8">
            <CardContent className="space-y-5">
              <div className="w-16 h-16 rounded-2xl bg-emerald-100 text-emerald-600 flex items-center justify-center mx-auto shadow-sm">
                <CheckCircle2 className="w-8 h-8" />
              </div>

              <div>
                <Badge className="bg-emerald-600 text-white border-0 text-xs mb-2">
                  Enquiry Submitted
                </Badge>
                <h2 className="text-2xl font-bold text-foreground">Welcome aboard, {fullName}!</h2>
                <p className="text-sm text-muted-foreground mt-1 max-w-md mx-auto">
                  Thank you. Your reference is {submitted}. Our team will call you within one working day.
                </p>
              </div>

              <div className="flex flex-col sm:flex-row items-center justify-center gap-3 pt-2">
                <Link href="/projects">
                  <Button variant="outline">
                    Return to CRM Projects
                  </Button>
                </Link>
              </div>
            </CardContent>
          </Card>
        )}
      </main>

      {/* Footer */}
      <footer className="border-t border-border bg-white py-4 text-center text-xs text-muted-foreground">
        Powered by our studio · Interior Designer Client Management System
      </footer>
    </div>
  );
}

"use client";

import { BrandLoader } from "@/components/brand/BrandLoader";
import { useState } from "react";
import { use, Suspense } from "react";
import { useSearchParams } from "next/navigation";
import { useAppStore } from "@/lib/store";
import { formatCurrency, formatDate, cn } from "@/lib/utils";
import { Card, CardContent } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { ApprovalPanel } from "@/components/approvals/ApprovalPanel";
import {
  XCircle, FileText, Download, ChevronDown, ChevronRight,
  ShieldCheck, AlertCircle,
} from "lucide-react";

export default function PortalBOQPage({ params }: { params: Promise<{ slug: string }> }) {
  return (
    <Suspense fallback={<BrandLoader label="Loading BOQ" />}>
      <PortalBOQContent params={params} />
    </Suspense>
  );
}

function PortalBOQContent({ params }: { params: Promise<{ slug: string }> }) {
  const { slug } = use(params);
  const { projects, boqs, clients, studioSettings, approveBOQVersion, rejectBOQVersion, me } = useAppStore();
  const searchParams = useSearchParams();

  const project = projects.find((p) => p.portal_slug === slug);
  const client = clients.find((c) => c.id === project?.client_id);
  const projectBOQs = boqs.filter((b) => b.project_id === project?.id && b.status !== "draft").sort((a, b) => b.version_number - a.version_number);
  // Pick active or latest submitted BOQ
  const activeBOQ = projectBOQs.find((b) => b.id === searchParams.get("version")) || projectBOQs.find((b) => b.status === "submitted") || projectBOQs.find((b) => b.is_active) || projectBOQs[0];

  const [expandedSections, setExpandedSections] = useState<Record<string, boolean>>({
    sec_1: true,
    sec_2: true,
    sec_3: true,
  });

  if (!project) {
    return <div className="p-8 text-center text-muted-foreground">Project not found.</div>;
  }

  if (!activeBOQ) {
    return (
      <div className="text-center py-16 bg-white rounded-2xl border border-border p-8 shadow-sm">
        <FileText className="w-12 h-12 text-muted-foreground/40 mx-auto mb-3" />
        <h2 className="text-lg font-bold text-foreground">No BOQ Published Yet</h2>
        <p className="text-sm text-muted-foreground mt-1 max-w-md mx-auto">
          Your interior designer is currently finalizing the Bill of Quantities. It will appear here once submitted for your review.
        </p>
      </div>
    );
  }

  const toggleSection = (secId: string) => {
    setExpandedSections((prev) => ({ ...prev, [secId]: !prev[secId] }));
  };

  const handlePrint = () => {
    window.print();
  };

  return (
    <div className="space-y-6">
      {/* Top Banner / Actions */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <div className="flex items-center gap-2 mb-1">
            <h1 className="text-2xl font-bold text-foreground">Bill of Quantities (BOQ)</h1>
            <Badge variant="outline" className="text-xs font-semibold">
              v{activeBOQ.version_number}
            </Badge>
          </div>
          <p className="text-sm text-muted-foreground">
            Detailed room-wise breakdown of materials, carpentry, and finishes.
          </p>
        </div>

        <div className="flex items-center gap-2">
          <Button variant="outline" size="sm" onClick={handlePrint} className="gap-1.5">
            <Download className="w-4 h-4" />
            Print / Save PDF
          </Button>
        </div>
      </div>

      {projectBOQs.length > 1 && <div className="flex flex-wrap items-center gap-3"><span className="text-sm font-medium">Estimate versions</span>{projectBOQs.map((b) => <a key={b.id} href={`/portal/${slug}/boq?version=${b.id}`} aria-current={b.id === activeBOQ.id ? "page" : undefined} className={cn("rounded-lg border px-3 py-2 text-xs font-medium", b.id === activeBOQ.id ? "bg-primary text-primary-foreground" : "bg-card text-muted-foreground")}>v{b.version_number} · {b.status}</a>)}</div>}
      {/* Status Alert Banner */}
      {activeBOQ.status === "approved" ? (
        <Card className="border-emerald-200 bg-emerald-50/70 shadow-sm">
          <CardContent className="p-4 flex items-center gap-3">
            <ShieldCheck className="w-6 h-6 text-emerald-600 flex-shrink-0" />
            <div className="flex-1">
              <p className="text-sm font-semibold text-emerald-900">
                BOQ Approved by {activeBOQ.approved_by || client?.full_name || "Client"}
              </p>
              <p className="text-xs text-emerald-700">
                {activeBOQ.approved_at ? `Recorded on ${formatDate(activeBOQ.approved_at)}.` : "Approval recorded."} {activeBOQ.is_active ? "This is the current approved estimate." : "This is a previous approved version."}
              </p>
              {activeBOQ.approval_note && <p className="mt-2 text-sm text-primary">{activeBOQ.approval_note}</p>}
            </div>
            <Badge className="bg-emerald-600 text-white border-0 text-xs">Approved</Badge>
          </CardContent>
        </Card>
      ) : activeBOQ.status === "submitted" && me.kind === "client" ? (
        <ApprovalPanel
          title="Approve this estimate"
          confirmText="I confirm that I have reviewed the items, quantities and rates in this estimate and approve them for site execution."
          defaultSigner={client?.full_name ?? ""}
          onApprove={(signer, note) => approveBOQVersion(activeBOQ.id, signer, note)}
          onReject={(signer, reason) => rejectBOQVersion(activeBOQ.id, signer, reason)}
        />
      ) : activeBOQ.status === "rejected" ? (
        <Card className="border-red-200 bg-red-50/70 shadow-sm">
          <CardContent className="p-4 flex items-center gap-3">
            <XCircle className="w-6 h-6 text-red-600 flex-shrink-0" />
            <div>
              <p className="text-sm font-semibold text-red-900">Revision Requested</p>
              <p className="text-xs text-red-700">
                Your feedback has been sent to the design team. An updated version will be uploaded soon.
              </p>
            </div>
          </CardContent>
        </Card>
      ) : null}

      {/* Summary Cards */}
      <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
        <Card className="shadow-sm">
          <CardContent className="p-4">
            <p className="text-xs font-medium text-muted-foreground">Items & Fee Subtotal</p>
            <p className="text-2xl font-bold text-foreground mt-1">
              {formatCurrency(Math.round(activeBOQ.grand_total / (1 + (activeBOQ.gst_percent || 18) / 100)))}
            </p>
            <p className="text-[11px] text-muted-foreground mt-0.5">Excluding GST ({activeBOQ.gst_percent || studioSettings.gst_rate}%)</p>
          </CardContent>
        </Card>
        <Card className="shadow-sm">
          <CardContent className="p-4">
            <p className="text-xs font-medium text-muted-foreground">GST Amount ({activeBOQ.gst_percent || studioSettings.gst_rate}%)</p>
            <p className="text-2xl font-bold text-slate-700 mt-1">
              {formatCurrency(activeBOQ.grand_total - Math.round(activeBOQ.grand_total / (1 + (activeBOQ.gst_percent || 18) / 100)))}
            </p>
            <p className="text-[11px] text-muted-foreground mt-0.5">Applicable tax</p>
          </CardContent>
        </Card>
        <Card className="shadow-sm bg-slate-900 text-white">
          <CardContent className="p-4">
            <p className="text-xs font-medium text-slate-400">Total Payable Value</p>
            <p className="text-2xl font-bold text-white mt-1">
              {formatCurrency(activeBOQ.grand_total)}
            </p>
            <p className="text-[11px] text-slate-400 mt-0.5">Inclusive of GST</p>
          </CardContent>
        </Card>
      </div>

      {/* Room-wise Sections Accordion */}
      <div className="space-y-4">
        {activeBOQ.sections.map((section) => {
          const isExpanded = expandedSections[section.id] ?? true;
          return (
            <Card key={section.id} className="shadow-sm overflow-hidden border border-border">
              <button
                type="button"
                onClick={() => toggleSection(section.id)}
                className="w-full flex items-center justify-between p-4 bg-slate-50/70 hover:bg-slate-100/80 transition-colors text-left"
              >
                <div className="flex items-center gap-2">
                  {isExpanded ? (
                    <ChevronDown className="w-4 h-4 text-muted-foreground" />
                  ) : (
                    <ChevronRight className="w-4 h-4 text-muted-foreground" />
                  )}
                  <h3 className="font-semibold text-foreground text-base">{section.name}</h3>
                  <Badge variant="secondary" className="text-xs font-normal ml-2">
                    {section.items.length} items
                  </Badge>
                </div>
                <div className="text-right">
                  <span className="font-bold text-foreground">
                    {formatCurrency(section.subtotal)}
                  </span>
                </div>
              </button>

              {isExpanded && (
                <div className="overflow-x-auto">
                  <table className="w-full text-sm">
                    <thead>
                      <tr className="border-b border-border bg-white text-muted-foreground text-xs uppercase tracking-wider">
                        <th className="py-2.5 px-4 text-left font-medium">Item & Description</th>
                        <th className="py-2.5 px-4 text-center font-medium">Qty</th>
                        <th className="py-2.5 px-4 text-center font-medium">Unit</th>
                        <th className="py-2.5 px-4 text-right font-medium">Rate</th>
                        <th className="py-2.5 px-4 text-right font-medium">Amount</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-border bg-white">
                      {section.items.map((item) => (
                        <tr key={item.id} className="hover:bg-slate-50/50">
                          <td className="py-3 px-4">
                            <p className="font-medium text-foreground">{item.description}</p>
                            {item.specifications && (
                              <p className="text-xs text-muted-foreground mt-0.5 max-w-lg leading-relaxed">
                                {item.specifications}
                              </p>
                            )}
                          </td>
                          <td className="py-3 px-4 text-center font-medium">{item.quantity}</td>
                          <td className="py-3 px-4 text-center text-muted-foreground text-xs">{item.unit}</td>
                          <td className="py-3 px-4 text-right text-muted-foreground">
                            {formatCurrency(item.unit_rate || 0)}
                          </td>
                          <td className="py-3 px-4 text-right font-semibold text-foreground">
                            {formatCurrency(item.total || 0)}
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              )}
            </Card>
          );
        })}
      </div>
    </div>
  );
}

"use client";

import { BrandLoader } from "@/components/brand/BrandLoader";
import { useState } from "react";
import { use, Suspense } from "react";
import { useAppStore } from "@/lib/store";
import { formatDate, formatFileSize } from "@/lib/utils";
import { Card, CardContent } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import {
  Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter,
} from "@/components/ui/dialog";
import {
  Folder, FileText, Image as ImageIcon, Download, Eye, ExternalLink,
  Layers, CheckCircle2
} from "lucide-react";
import { ProjectFile } from "@/types";

export default function PortalFilesPage({ params }: { params: Promise<{ slug: string }> }) {
  return (
    <Suspense fallback={<BrandLoader label="Loading files" />}>
      <PortalFilesContent params={params} />
    </Suspense>
  );
}

function PortalFilesContent({ params }: { params: Promise<{ slug: string }> }) {
  const { slug } = use(params);
  const { projects, files } = useAppStore();

  const project = projects.find((p) => p.portal_slug === slug);
  const clientFiles = files.filter(
    (f) => f.project_id === project?.id && f.is_client_visible
  );

  const [activeCategory, setActiveCategory] = useState<string>("all");
  const [previewFile, setPreviewFile] = useState<ProjectFile | null>(null);

  if (!project) {
    return <div className="p-8 text-center text-muted-foreground">Project not found.</div>;
  }

  const filteredFiles = clientFiles.filter(
    (f) => activeCategory === "all" || f.category === activeCategory
  );

  const categories = [
    { key: "all", label: `All Files (${clientFiles.length})` },
    { key: "3d_render", label: "3D Renders" },
    { key: "2d_drawing", label: "2D Drawings" },
    { key: "specification", label: "Material Specs" },
    { key: "handover", label: "Handover Docs" },
  ];

  return (
    <div className="space-y-6">
      {/* Header */}
      <div>
        <h1 className="text-2xl font-bold text-foreground">Project Files & Deliverables</h1>
        <p className="text-sm text-muted-foreground">
          Access high-resolution 3D renders, approved working drawings, and material selection sheets.
        </p>
      </div>

      {/* Categories */}
      <div className="flex flex-wrap gap-2 border-b border-border pb-3">
        {categories.map((cat) => (
          <button
            key={cat.key}
            onClick={() => setActiveCategory(cat.key)}
            className={`px-3 py-1.5 rounded-lg text-xs font-medium transition-colors ${
              activeCategory === cat.key
                ? "bg-slate-900 text-white"
                : "text-muted-foreground hover:bg-slate-100 hover:text-foreground"
            }`}
          >
            {cat.label}
          </button>
        ))}
      </div>

      {/* Grid of Files */}
      <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 gap-4">
        {filteredFiles.map((file) => {
          const isImage = file.file_type.includes("image");
          return (
            <Card
              key={file.id}
              className="overflow-hidden shadow-sm hover:border-primary/30 transition-all flex flex-col group cursor-pointer"
              onClick={() => setPreviewFile(file)}
            >
              <div className="relative aspect-video bg-slate-100 overflow-hidden flex items-center justify-center">
                {isImage ? (
                  <img
                    src={file.file_url}
                    alt={file.file_name}
                    className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-300"
                  />
                ) : (
                  <div className="flex flex-col items-center text-muted-foreground">
                    <FileText className="w-10 h-10 opacity-40 mb-1" />
                    <span className="text-[10px] uppercase font-semibold tracking-wider">
                      {file.file_type.split("/")[1] || "DOCUMENT"}
                    </span>
                  </div>
                )}
                <Badge
                  variant="secondary"
                  className="absolute top-2 left-2 text-[10px] bg-white/90 backdrop-blur-sm shadow-xs capitalize"
                >
                  {file.category.replace("_", " ")}
                </Badge>
              </div>

              <CardContent className="p-3.5 flex-1 flex flex-col justify-between">
                <div>
                  <p className="font-semibold text-sm text-foreground truncate">{file.file_name}</p>
                  <p className="text-xs text-muted-foreground mt-0.5">
                    Added {formatDate(file.created_at)}
                  </p>
                </div>

                <div className="flex items-center justify-between pt-3 mt-3 border-t border-border">
                  <span className="text-xs text-muted-foreground">
                    {formatFileSize(file.file_size_bytes || 0)}
                  </span>
                  <div className="flex items-center gap-1">
                    <Button
                      size="sm"
                      variant="ghost"
                      className="h-7 px-2 text-xs text-primary"
                      onClick={(e) => {
                        e.stopPropagation();
                        setPreviewFile(file);
                      }}
                    >
                      <Eye className="w-3.5 h-3.5 mr-1" /> View
                    </Button>
                    <a
                      href={file.file_url}
                      target="_blank"
                      rel="noopener noreferrer"
                      download
                      onClick={(e) => e.stopPropagation()}
                      className="inline-flex items-center justify-center h-7 px-2 text-xs rounded-md hover:bg-slate-100 text-slate-700"
                    >
                      <Download className="w-3.5 h-3.5" />
                    </a>
                  </div>
                </div>
              </CardContent>
            </Card>
          );
        })}
      </div>

      {filteredFiles.length === 0 && (
        <div className="text-center py-16 bg-white rounded-xl border border-border">
          <Folder className="w-12 h-12 text-muted-foreground/30 mx-auto mb-2" />
          <p className="text-sm font-semibold text-foreground">No files in this category</p>
          <p className="text-xs text-muted-foreground mt-0.5">
            Files shared by your design team will appear here automatically.
          </p>
        </div>
      )}

      {/* Preview Dialog */}
      {previewFile && (
        <Dialog open={!!previewFile} onOpenChange={(open) => !open && setPreviewFile(null)}>
          <DialogContent className="max-w-3xl">
            <DialogHeader>
              <div className="flex items-center gap-2 mb-1">
                <Badge variant="outline" className="capitalize">
                  {previewFile.category.replace("_", " ")}
                </Badge>
                <span className="text-xs text-muted-foreground">
                  Uploaded on {formatDate(previewFile.created_at)}
                </span>
              </div>
              <DialogTitle className="text-base truncate">{previewFile.file_name}</DialogTitle>
            </DialogHeader>

            <div className="py-2">
              {previewFile.file_type.includes("image") ? (
                <div className="rounded-lg overflow-hidden border border-border max-h-[500px] flex items-center justify-center bg-black/5">
                  <img
                    src={previewFile.file_url}
                    alt={previewFile.file_name}
                    className="max-h-[480px] w-auto object-contain"
                  />
                </div>
              ) : (
                <div className="p-12 text-center bg-slate-50 rounded-lg border border-border">
                  <FileText className="w-16 h-16 text-muted-foreground/40 mx-auto mb-2" />
                  <p className="text-sm font-medium">{previewFile.file_name}</p>
                  <p className="text-xs text-muted-foreground mt-1">
                    {formatFileSize(previewFile.file_size_bytes || 0)} · Document Preview
                  </p>
                </div>
              )}
            </div>

            <DialogFooter className="flex items-center justify-between sm:justify-between w-full">
              <span className="text-xs text-muted-foreground">
                Author: {previewFile.uploaded_by}
              </span>
              <div className="flex gap-2">
                <Button variant="outline" size="sm" onClick={() => setPreviewFile(null)}>
                  Close
                </Button>
                <a
                  href={previewFile.file_url}
                  target="_blank"
                  rel="noopener noreferrer"
                  className="inline-flex items-center justify-center px-4 py-2 text-sm font-medium rounded-md gradient-primary text-white"
                >
                  <Download className="w-4 h-4 mr-1.5" /> Download File
                </a>
              </div>
            </DialogFooter>
          </DialogContent>
        </Dialog>
      )}
    </div>
  );
}

"use client";

import { BrandLoader } from "@/components/brand/BrandLoader";
import { useState, useRef } from "react";
import { use, Suspense } from "react";
import { useAppStore } from "@/lib/store";
import { formatRelativeTime, cn } from "@/lib/utils";
import { Card, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Avatar, AvatarFallback } from "@/components/ui/avatar";
import { Send, Phone, MessageSquare, Sparkles, Building2, User, Paperclip } from "lucide-react";
import { Message } from "@/types";

export default function PortalMessagesPage({ params }: { params: Promise<{ slug: string }> }) {
  return (
    <Suspense fallback={<BrandLoader label="Loading messages" />}>
      <PortalMessagesContent params={params} />
    </Suspense>
  );
}

function PortalMessagesContent({ params }: { params: Promise<{ slug: string }> }) {
  const { slug } = use(params);
  const { projects, messages, clients, studioSettings, addMessage, me } = useAppStore();

  const project = projects.find((p) => p.portal_slug === slug);
  const client = clients.find((c) => c.id === project?.client_id);
  const projectMessages = messages.filter((m) => m.project_id === project?.id);

  const [inputContent, setInputContent] = useState("");
  const fileInputRef = useRef<HTMLInputElement>(null);

  if (!project) {
    return <div className="p-8 text-center text-muted-foreground">Project not found.</div>;
  }

  const handleSendMessage = (e: React.FormEvent) => {
    e.preventDefault();
    if (!inputContent.trim()) return;

    addMessage({
      project_id: project.id,
      content: inputContent.trim(),
    });
    setInputContent("");
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const fileUrl = URL.createObjectURL(file);
    
    addMessage({
      project_id: project.id,
      content: "",
      file_url: fileUrl,
      file_name: file.name,
    });
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const QUICK_QUESTIONS = [
    "When is the next site visit scheduled?",
    "Could you share the laminate catalog link?",
    "Please check the electrical points in master bedroom.",
    "Approved the paint shade swatch!",
  ];

  return (
    <div className="space-y-4">
      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 pb-2 border-b border-border">
        <div>
          <h1 className="text-2xl font-bold text-foreground">Project Chat</h1>
          <p className="text-sm text-muted-foreground">
            Direct communication with your lead designer and site supervisor.
          </p>
        </div>
        <div className="flex items-center gap-2">
          <a
            href={`https://wa.me/${studioSettings.phone.replace(/[^0-9]/g, "")}`}
            target="_blank"
            rel="noopener noreferrer"
            className="inline-flex items-center gap-1.5 text-xs font-semibold px-3 py-1.5 rounded-lg bg-emerald-50 text-emerald-700 hover:bg-emerald-100 border border-emerald-200 transition-colors"
          >
            <Phone className="w-3.5 h-3.5 text-emerald-600" /> WhatsApp Studio
          </a>
        </div>
      </div>

      {/* Chat Container */}
      <Card className="shadow-sm border border-border flex flex-col h-[600px] overflow-hidden bg-white">
        {/* Messages Feed */}
        <div className="flex-1 p-4 overflow-y-auto space-y-4 bg-slate-50/50">
          <div className="text-center my-2">
            <span className="text-[11px] bg-slate-200/70 text-slate-600 px-3 py-1 rounded-full font-medium">
              Project Communication Channel
            </span>
          </div>

          {projectMessages.map((msg) => {
            const isClient = msg.sender_id === me.id;
            return (
              <div
                key={msg.id}
                className={cn(
                  "flex gap-3 max-w-[85%] md:max-w-[70%]",
                  isClient ? "ml-auto flex-row-reverse" : "mr-auto"
                )}
              >
                <Avatar className="w-8 h-8 flex-shrink-0 mt-0.5">
                  <AvatarFallback
                    className={cn(
                      "text-xs font-bold",
                      isClient
                        ? "bg-primary text-white"
                        : "bg-slate-200 text-slate-700"
                    )}
                  >
                    {isClient ? <User className="w-4 h-4" /> : <Building2 className="w-4 h-4" />}
                  </AvatarFallback>
                </Avatar>

                <div>
                  <div
                    className={cn(
                      "flex items-center gap-2 mb-1 text-xs",
                      isClient ? "justify-end" : "justify-start"
                    )}
                  >
                    <span className="font-semibold text-foreground">{msg.sender_name}</span>
                    <span className="text-muted-foreground text-[10px]">
                      {formatRelativeTime(msg.created_at)}
                    </span>
                  </div>

                  <div
                    className={cn(
                      "p-3 rounded-2xl text-sm leading-relaxed shadow-xs",
                      isClient
                        ? "bg-primary text-white rounded-tr-xs"
                        : "bg-white text-slate-800 border border-border rounded-tl-xs"
                    )}
                  >
                    {msg.content && <p>{msg.content}</p>}
                    {msg.file_url && (
                      <div className="mt-2 mb-1 rounded-md overflow-hidden max-w-[200px] border border-black/10">
                        <img src={msg.file_url} alt="Attachment" className="w-full h-auto object-cover block" />
                      </div>
                    )}
                  </div>
                </div>
              </div>
            );
          })}

          {projectMessages.length === 0 && (
            <div className="text-center py-16 text-muted-foreground">
              <MessageSquare className="w-10 h-10 opacity-30 mx-auto mb-2" />
              <p className="text-sm font-medium">No messages yet</p>
              <p className="text-xs mt-0.5">Start the conversation by sending a message below.</p>
            </div>
          )}
        </div>

        {/* Quick Suggestion Chips */}
        <div className="px-3 py-2 bg-slate-50 border-t border-border flex items-center gap-2 overflow-x-auto text-xs whitespace-nowrap scrollbar-none">
          <span className="text-[11px] font-semibold text-muted-foreground flex items-center gap-1">
            <Sparkles className="w-3 h-3 text-primary" /> Suggestions:
          </span>
          {QUICK_QUESTIONS.map((q, idx) => (
            <button
              key={idx}
              type="button"
              onClick={() => setInputContent(q)}
              className="text-xs px-2.5 py-1 rounded-full bg-white border border-border hover:border-primary/30 hover:text-primary transition-colors cursor-pointer text-slate-700"
            >
              {q}
            </button>
          ))}
        </div>

        {/* Input Bar */}
        <form onSubmit={handleSendMessage} className="p-3 bg-white border-t border-border flex gap-2 items-center">
          <input 
            type="file" 
            ref={fileInputRef} 
            className="hidden" 
            accept="image/*"
            onChange={handleFileUpload} 
          />
          <Button 
            type="button" 
            variant="ghost" 
            size="icon" 
            className="text-muted-foreground hover:text-foreground shrink-0"
            onClick={() => fileInputRef.current?.click()}
          >
            <Paperclip className="w-5 h-5" />
          </Button>
          <Input
            value={inputContent}
            onChange={(e) => setInputContent(e.target.value)}
            placeholder="Type a message or question for your designer..."
            className="flex-1 text-sm bg-slate-50 border-slate-200 focus-visible:bg-white"
          />
          <Button
            type="submit"
            disabled={!inputContent.trim()}
            className="gradient-primary border-0 text-white gap-1.5 px-4"
          >
            <Send className="w-4 h-4" />
            <span className="hidden sm:inline">Send</span>
          </Button>
        </form>
      </Card>
    </div>
  );
}

"use client";

import { BrandLoader } from "@/components/brand/BrandLoader";
import { useState } from "react";
import { use, Suspense } from "react";
import { useAppStore } from "@/lib/store";
import { PhotoInput } from "@/components/files/PhotoInput";
import { formatDate, getPriorityColor, getStatusColor, cn } from "@/lib/utils";
import { Card, CardContent } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import {
  Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription, DialogFooter,
} from "@/components/ui/dialog";
import {
  CheckCircle2, Plus, AlertCircle, Camera, Check, Clock, Sparkles
} from "lucide-react";
import { Snag, SnagPriority } from "@/types";

export default function PortalSnagsPage({ params }: { params: Promise<{ slug: string }> }) {
  return (
    <Suspense fallback={<BrandLoader label="Loading snags" />}>
      <PortalSnagsContent params={params} />
    </Suspense>
  );
}

function PortalSnagsContent({ params }: { params: Promise<{ slug: string }> }) {
  const { slug } = use(params);
  const { projects, snags, addSnag, updateSnagStatus, addSnagComment } = useAppStore();

  const project = projects.find((p) => p.portal_slug === slug);
  const projectSnags = snags.filter((s) => s.project_id === project?.id);

  const [activeFilter, setActiveFilter] = useState<"all" | "open" | "fixed" | "closed">("all");
  const [showReportModal, setShowReportModal] = useState(false);
  const [selectedSnag, setSelectedSnag] = useState<Snag | null>(null);

  // New Snag form state
  const [room, setRoom] = useState(project?.rooms?.[0]?.name || "Living Room");
  const [description, setDescription] = useState("");
  const [priority, setPriority] = useState<SnagPriority>("major");
  const [photoUrl, setPhotoUrl] = useState("");

  if (!project) {
    return <div className="p-8 text-center text-muted-foreground">Project not found.</div>;
  }

  const filteredSnags = projectSnags.filter((s) => {
    if (activeFilter === "all") return true;
    if (activeFilter === "open") return !["fixed", "verified", "closed"].includes(s.status);
    if (activeFilter === "fixed") return ["fixed", "verified"].includes(s.status);
    if (activeFilter === "closed") return s.status === "closed";
    return true;
  });

  const openCount = projectSnags.filter((s) => !["closed", "verified"].includes(s.status)).length;
  const fixedCount = projectSnags.filter((s) => ["fixed", "verified"].includes(s.status)).length;

  const handleCreateSnag = (e: React.FormEvent) => {
    e.preventDefault();
    if (!description.trim()) return;

    const roomObj = project.rooms?.find(r => r.name === room);
    addSnag({
      project_id: project.id,
      room_id: roomObj?.id,
      title: description.slice(0, 50),
      description,
      priority,
      before_photo_url: photoUrl || undefined,
    });

    setDescription("");
    setPhotoUrl("");
    setShowReportModal(false);
  };

  const handleCloseSnag = (snagId: string) => {
    updateSnagStatus(snagId, "closed", "Client");
    setSelectedSnag(null);
  };

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold text-foreground">Snag List & Quality Checks</h1>
          <p className="text-sm text-muted-foreground">
            Track touch-ups, defect fixes, and final handover verification items.
          </p>
        </div>
        <Button
          onClick={() => setShowReportModal(true)}
          className="gradient-primary border-0 text-white gap-2 shadow-sm"
        >
          <Plus className="w-4 h-4" />
          Report an Issue
        </Button>
      </div>

      {/* Overview Cards */}
      <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
        <Card>
          <CardContent className="p-4">
            <p className="text-xs text-muted-foreground">Total Raised</p>
            <p className="text-2xl font-bold text-foreground mt-1">{projectSnags.length}</p>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="p-4">
            <p className="text-xs text-muted-foreground">Pending Resolution</p>
            <p className="text-2xl font-bold text-amber-600 mt-1">{openCount}</p>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="p-4">
            <p className="text-xs text-muted-foreground">Ready for Sign-off</p>
            <p className="text-2xl font-bold text-primary mt-1">{fixedCount}</p>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="p-4">
            <p className="text-xs text-muted-foreground">Closed / Verified</p>
            <p className="text-2xl font-bold text-emerald-600 mt-1">
              {projectSnags.filter((s) => s.status === "closed").length}
            </p>
          </CardContent>
        </Card>
      </div>

      {/* Filter Tabs */}
      <div className="flex gap-2 border-b border-border pb-2">
        {(
          [
            { key: "all", label: `All (${projectSnags.length})` },
            { key: "open", label: `Open (${openCount})` },
            { key: "fixed", label: `Fixed / Verify (${fixedCount})` },
            { key: "closed", label: `Closed (${projectSnags.filter((s) => s.status === "closed").length})` },
          ] as const
        ).map((tab) => (
          <button
            key={tab.key}
            onClick={() => setActiveFilter(tab.key)}
            className={cn(
              "px-3 py-1.5 rounded-lg text-xs font-medium transition-colors",
              activeFilter === tab.key
                ? "bg-slate-900 text-white"
                : "text-muted-foreground hover:bg-slate-100 hover:text-foreground"
            )}
          >
            {tab.label}
          </button>
        ))}
      </div>

      {/* Snag List */}
      <div className="space-y-3">
        {filteredSnags.map((snag) => (
          <Card
            key={snag.id}
            onClick={() => setSelectedSnag(snag)}
            className="cursor-pointer hover:border-primary/20 transition-all shadow-sm"
          >
            <CardContent className="p-4">
              <div className="flex flex-col sm:flex-row sm:items-start justify-between gap-4">
                <div className="flex items-start gap-3.5">
                  {snag.before_photo_url ? (
                    <img
                      src={snag.before_photo_url}
                      alt={snag.room_name}
                      className="w-16 h-16 rounded-lg object-cover flex-shrink-0 border border-border"
                    />
                  ) : (
                    <div className="w-16 h-16 rounded-lg bg-slate-100 flex items-center justify-center flex-shrink-0 text-slate-400">
                      <Camera className="w-6 h-6 opacity-40" />
                    </div>
                  )}

                  <div>
                    <div className="flex flex-wrap items-center gap-2 mb-1.5">
                      <Badge variant="outline" className="font-semibold text-xs">
                        {snag.room_name}
                      </Badge>
                      <Badge className={cn("text-[10px] border-0", getPriorityColor(snag.priority))}>
                        {snag.priority}
                      </Badge>
                      <Badge className={cn("text-[10px] border-0", getStatusColor(snag.status))}>
                        {snag.status.replace("_", " ")}
                      </Badge>
                    </div>
                    <p className="text-sm font-medium text-foreground leading-snug">
                      {snag.description}
                    </p>
                    <p className="text-xs text-muted-foreground mt-1 flex items-center gap-1">
                      <Clock className="w-3 h-3" /> Reported {formatDate(snag.created_at)}
                    </p>
                  </div>
                </div>

                <div className="flex sm:flex-col items-end justify-between sm:justify-start gap-2">
                  {["fixed", "verified"].includes(snag.status) && (
                    <Button
                      size="sm"
                      onClick={(e) => {
                        e.stopPropagation();
                        handleCloseSnag(snag.id);
                      }}
                      className="bg-emerald-600 hover:bg-emerald-700 text-white text-xs h-8 gap-1.5"
                    >
                      <Check className="w-3.5 h-3.5" /> Confirm Fixed
                    </Button>
                  )}
                  {snag.status === "closed" && (
                    <span className="text-xs font-semibold text-emerald-600 flex items-center gap-1">
                      <CheckCircle2 className="w-4 h-4" /> Verified & Closed
                    </span>
                  )}
                </div>
              </div>
            </CardContent>
          </Card>
        ))}

        {filteredSnags.length === 0 && (
          <div className="text-center py-12 bg-white rounded-xl border border-border">
            <CheckCircle2 className="w-10 h-10 text-emerald-500 mx-auto mb-2 opacity-60" />
            <p className="text-sm font-semibold text-foreground">No snags found</p>
            <p className="text-xs text-muted-foreground mt-0.5">
              Everything in this category is smooth and verified.
            </p>
          </div>
        )}
      </div>

      {/* Report Snag Dialog */}
      <Dialog open={showReportModal} onOpenChange={setShowReportModal}>
        <DialogContent className="max-w-md">
          <DialogHeader>
            <DialogTitle>Report an Issue or Snag</DialogTitle>
            <DialogDescription>
              Notice a scratch, loose fit, or touch-up needed? Tell the design team and we will fix it.
            </DialogDescription>
          </DialogHeader>

          <form onSubmit={handleCreateSnag} className="space-y-4 py-2">
            <div>
              <label className="text-xs font-semibold text-foreground block mb-1">Select Room *</label>
              <select
                value={room}
                onChange={(e) => setRoom(e.target.value)}
                className="w-full text-sm border border-input rounded-md px-3 py-2 bg-background focus:outline-none focus:ring-2 focus:ring-ring"
              >
                {project.rooms && project.rooms.length > 0 ? (
                  project.rooms.map((r) => (
                    <option key={r.id} value={r.name}>
                      {r.name}
                    </option>
                  ))
                ) : (
                  <>
                    <option value="Living Room">Living Room</option>
                    <option value="Master Bedroom">Master Bedroom</option>
                    <option value="Kitchen">Kitchen</option>
                    <option value="Balcony">Balcony</option>
                    <option value="Bathroom">Bathroom</option>
                  </>
                )}
              </select>
            </div>

            <div>
              <label className="text-xs font-semibold text-foreground block mb-1">Priority</label>
              <div className="grid grid-cols-3 gap-2">
                {(["minor", "major", "critical"] as const).map((p) => (
                  <button
                    type="button"
                    key={p}
                    onClick={() => setPriority(p)}
                    className={cn(
                      "text-xs py-1.5 rounded-md border text-center capitalize transition-colors font-medium",
                      priority === p
                        ? "border-primary bg-primary text-white"
                        : "border-border hover:bg-slate-50 text-foreground"
                    )}
                  >
                    {p}
                  </button>
                ))}
              </div>
            </div>

            <div>
              <label className="text-xs font-semibold text-foreground block mb-1">Issue Description *</label>
              <Textarea
                required
                value={description}
                onChange={(e) => setDescription(e.target.value)}
                placeholder="e.g., Soft-close hinge on the left wardrobe shutter is sticking slightly."
                rows={3}
              />
            </div>

            <div>
              <PhotoInput projectId={project.id} label="Photo of the issue" onUploaded={setPhotoUrl} />
            </div>

            <DialogFooter className="gap-2 sm:gap-0 pt-2">
              <Button type="button" variant="outline" onClick={() => setShowReportModal(false)}>
                Cancel
              </Button>
              <Button type="submit" className="gradient-primary border-0 text-white">
                Submit Snag
              </Button>
            </DialogFooter>
          </form>
        </DialogContent>
      </Dialog>

      {/* Snag Detail Dialog */}
      {selectedSnag && (
        <Dialog open={!!selectedSnag} onOpenChange={(open) => !open && setSelectedSnag(null)}>
          <DialogContent className="max-w-lg">
            <DialogHeader>
              <div className="flex items-center gap-2 mb-1">
                <Badge variant="outline">{selectedSnag.room_name}</Badge>
                <Badge className={cn("text-xs border-0", getStatusColor(selectedSnag.status))}>
                  {selectedSnag.status.replace("_", " ")}
                </Badge>
              </div>
              <DialogTitle className="text-lg">{selectedSnag.description}</DialogTitle>
            </DialogHeader>

            <div className="space-y-4 py-2">
              {/* Photo Comparison */}
              <div className="grid grid-cols-2 gap-3">
                <div>
                  <p className="text-xs font-semibold text-muted-foreground mb-1.5">Original Issue Photo</p>
                  {selectedSnag.before_photo_url ? (
                    <img
                      src={selectedSnag.before_photo_url}
                      alt="Before"
                      className="w-full h-36 rounded-lg object-cover border border-border"
                    />
                  ) : (
                    <div className="w-full h-36 rounded-lg bg-slate-100 flex items-center justify-center text-xs text-muted-foreground">
                      No photo provided
                    </div>
                  )}
                </div>
                <div>
                  <p className="text-xs font-semibold text-muted-foreground mb-1.5">Resolution / Fixed Photo</p>
                  {selectedSnag.after_photo_url ? (
                    <img
                      src={selectedSnag.after_photo_url}
                      alt="After"
                      className="w-full h-36 rounded-lg object-cover border border-emerald-300"
                    />
                  ) : (
                    <div className="w-full h-36 rounded-lg bg-slate-100 flex items-center justify-center text-xs text-muted-foreground">
                      Fix in progress
                    </div>
                  )}
                </div>
              </div>

              {/* Status Action */}
              {["fixed", "verified"].includes(selectedSnag.status) && (
                <div className="p-3 bg-emerald-50 rounded-lg border border-emerald-200">
                  <p className="text-xs font-semibold text-emerald-900 mb-1">The designer marked this as fixed!</p>
                  <p className="text-xs text-emerald-700 mb-3">
                    Please inspect this on site or check the photo. If satisfactory, click below to mark verified.
                  </p>
                  <Button
                    size="sm"
                    onClick={() => handleCloseSnag(selectedSnag.id)}
                    className="bg-emerald-600 hover:bg-emerald-700 text-white w-full gap-2"
                  >
                    <Check className="w-4 h-4" /> I Confirm This Is Resolved (Close Snag)
                  </Button>
                </div>
              )}
            </div>

            <DialogFooter>
              <Button variant="outline" onClick={() => setSelectedSnag(null)}>
                Close
              </Button>
            </DialogFooter>
          </DialogContent>
        </Dialog>
      )}
    </div>
  );
}

"use client";

import React, { useState } from "react";
import { BOQVersion, BOQLineItem } from "@/types";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from "@/components/ui/dialog";
import { formatCurrency, formatDate, getStatusColor, cn } from "@/lib/utils";
import { Download, FileText, Check, History, Plus, Trash2, BookOpen, Printer, X, ArrowRight } from "lucide-react";
import { useAppStore } from "@/lib/store";

export default function BOQTab({ projectId, boqVersions }: { projectId: string; boqVersions: BOQVersion[] }) {
  const { 
    itemLibrary, 
    addBOQVersion, 
    updateBOQVersion, 
    addLineItemToBOQ, 
    deleteLineItemFromBOQ,
    studioSettings
  } = useAppStore();

  const [selectedVersionId, setSelectedVersionId] = useState(boqVersions[0]?.id || "");
  const [compareModalOpen, setCompareModalOpen] = useState(false);
  const [exportModalOpen, setExportModalOpen] = useState(false);
  const [addItemModalOpen, setAddItemModalOpen] = useState(false);
  const [activeSectionId, setActiveSectionId] = useState<string>("");
  const [compareVersionId, setCompareVersionId] = useState<string>(boqVersions[1]?.id || boqVersions[0]?.id || "");

  // Form for adding new item
  const [newItemForm, setNewItemForm] = useState({
    description: "",
    unit: "sqft",
    quantity: 1,
    unit_rate: 100,
    remarks: "",
  });

  const selectedBoq = boqVersions.find((b) => b.id === selectedVersionId) || boqVersions[0];

  if (!boqVersions.length || !selectedBoq) {
    return (
      <div className="flex flex-col items-center justify-center py-20 text-center border-2 border-dashed border-border rounded-xl">
        <FileText className="w-10 h-10 text-muted-foreground mb-4" />
        <h3 className="font-semibold mb-1">No BOQ created yet</h3>
        <p className="text-sm text-muted-foreground mb-4">Start by creating your first Bill of Quantities version.</p>
        <Button 
          onClick={async () => {
            const r = await addBOQVersion({
              id: "", project_id: projectId, version_number: 1, version_label: "Initial estimate", status: "draft",
              gst_percent: studioSettings.gst_rate, discount_amount: 0, designer_fee: 0, grand_total: 0, created_at: "",
              sections: [{ id: "", boq_version_id: "", name: "General", category: "General", sort_order: 1, subtotal: 0, items: [] }],
            });
            if (r.ok && r.id) setSelectedVersionId(r.id);
          }}
          className="gradient-primary border-0"
        >
          Create First BOQ
        </Button>
      </div>
    );
  }

  const handleSubmitForApproval = () => {
    updateBOQVersion(selectedBoq.id, {
      status: "submitted",
    });
  };

  const handleCreateNewVersion = async () => {
    const nextVerNumber = Math.max(...boqVersions.map(v => v.version_number), 0) + 1;
    const clonedSections = (selectedBoq.sections || []).map(sec => ({
      ...sec,
      id: "",
      items: (sec.items || []).map(it => ({ ...it, id: "" }))
    }));

    const newVersion: BOQVersion = {
      id: "",
      project_id: projectId,
      version_number: nextVerNumber,
      version_label: `Revision v${nextVerNumber}`,
      status: "draft",
      grand_total: selectedBoq.grand_total,
      gst_percent: selectedBoq.gst_percent,
      discount_amount: selectedBoq.discount_amount,
      designer_fee: selectedBoq.designer_fee,
      created_by: "",
      created_at: "",
      sections: clonedSections,
    };
    const r = await addBOQVersion(newVersion);
    if (r.ok && r.id) setSelectedVersionId(r.id);
  };

  const handleAddItemSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!activeSectionId) return;
    addLineItemToBOQ(selectedBoq.id, activeSectionId, {
      description: newItemForm.description,
      unit: newItemForm.unit,
      quantity: Number(newItemForm.quantity),
      unit_rate: Number(newItemForm.unit_rate),
      remarks: newItemForm.remarks,
      sort_order: 99
    });
    setNewItemForm({ description: "", unit: "sqft", quantity: 1, unit_rate: 100, remarks: "" });
    setAddItemModalOpen(false);
  };

  // Version diff calculations for comparison
  const compareTargetBoq = boqVersions.find(b => b.id === compareVersionId) || selectedBoq;
  const netDifference = selectedBoq.grand_total - compareTargetBoq.grand_total;

  return (
    <div className="space-y-6">
      {/* Header controls */}
      <div className="flex flex-wrap items-center justify-between gap-4">
        <div className="flex items-center gap-3">
          <select
            className="h-9 px-3 rounded-md border border-input bg-card text-sm shadow-sm font-medium"
            value={selectedVersionId}
            onChange={(e) => setSelectedVersionId(e.target.value)}
          >
            {boqVersions.map((v) => (
              <option key={v.id} value={v.id}>
                Version {v.version_number} {v.version_label ? `— ${v.version_label}` : ""}
              </option>
            ))}
          </select>
          <Badge className={cn("border-0 uppercase text-[10px] tracking-wider", getStatusColor(selectedBoq.status))}>
            {selectedBoq.status}
          </Badge>
          <span className="text-xs text-muted-foreground hidden sm:inline">
            Created {formatDate(selectedBoq.created_at)}
          </span>
        </div>

        <div className="flex flex-wrap items-center gap-2">
          {boqVersions.length > 1 && (
            <Button variant="outline" size="sm" onClick={() => setCompareModalOpen(true)} className="gap-2 text-xs">
              <History className="w-3.5 h-3.5" /> Compare Versions
            </Button>
          )}
          <Button variant="outline" size="sm" onClick={() => setExportModalOpen(true)} className="gap-2 text-xs">
            <Download className="w-3.5 h-3.5" /> Export PDF
          </Button>
          <Button variant="outline" size="sm" onClick={handleCreateNewVersion} className="gap-2 text-xs">
            <Plus className="w-3.5 h-3.5" /> Save New Version
          </Button>
          {selectedBoq.status === "draft" && (
            <Button size="sm" onClick={handleSubmitForApproval} className="gradient-primary border-0 text-xs">
              Submit for Approval
            </Button>
          )}
        </div>
      </div>

      {selectedBoq.status !== "draft" && (
        <div className="text-xs text-amber-800 bg-amber-50 border border-amber-200 rounded-lg px-3 py-2">
          This version is locked. Create a new version to make changes.
        </div>
      )}

      {/* BOQ Summary Cards */}
      <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
        <Card>
          <CardContent className="p-4">
            <p className="text-xs font-medium text-muted-foreground mb-1">Subtotal (Excl. Tax)</p>
            <p className="text-xl font-bold text-foreground">
              {formatCurrency(selectedBoq.sections?.reduce((sum, s) => sum + s.subtotal, 0) || 0)}
            </p>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="p-4">
            <p className="text-xs font-medium text-muted-foreground mb-1">GST ({selectedBoq.gst_percent || 18}%)</p>
            <p className="text-xl font-bold text-muted-foreground">
              {formatCurrency(((selectedBoq.sections?.reduce((sum, s) => sum + s.subtotal, 0) || 0) * (selectedBoq.gst_percent || 18)) / 100)}
            </p>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="p-4">
            <p className="text-xs font-medium text-muted-foreground mb-1">Designer Fee</p>
            <p className="text-xl font-bold text-foreground">{formatCurrency(selectedBoq.designer_fee || 0)}</p>
          </CardContent>
        </Card>
        <Card className="bg-accent/50 border-primary/20">
          <CardContent className="p-4">
            <p className="text-xs font-medium text-primary mb-1">Grand Total</p>
            <p className="text-xl font-bold text-primary">{formatCurrency(selectedBoq.grand_total)}</p>
          </CardContent>
        </Card>
      </div>

      {/* BOQ Sections Table */}
      <Card>
        <div className="overflow-x-auto">
          <table className="w-full text-sm text-left">
            <thead className="bg-muted text-muted-foreground font-medium border-b border-border">
              <tr>
                <th className="py-3 px-4 w-5/12">Description</th>
                <th className="py-3 px-4 w-20 text-center">Unit</th>
                <th className="py-3 px-4 w-24 text-right">Qty</th>
                <th className="py-3 px-4 w-32 text-right">Rate</th>
                <th className="py-3 px-4 w-32 text-right">Total</th>
                <th className="py-3 px-4 w-16 text-center">Actions</th>
              </tr>
            </thead>
            <tbody>
              {selectedBoq.sections?.map((section) => (
                <React.Fragment key={section.id}>
                  {/* Section Header */}
                  <tr className="bg-muted/40 border-b border-border">
                    <td colSpan={4} className="py-2.5 px-4 font-semibold text-foreground">
                      <div className="flex items-center gap-2">
                        <span className="w-2 h-2 rounded-full bg-primary" />
                        {section.room_name} — {section.category}
                      </div>
                    </td>
                    <td className="py-2.5 px-4 font-semibold text-right text-foreground">
                      {formatCurrency(section.subtotal)}
                    </td>
                    <td className="py-2.5 px-4 text-center">
                      {selectedBoq.status === 'draft' && (
                        <Button 
                          variant="ghost" 
                          size="sm"
                          onClick={() => {
                            setActiveSectionId(section.id);
                            setAddItemModalOpen(true);
                          }}
                          className="h-7 text-xs text-primary gap-1 hover:text-primary"
                        >
                          <Plus className="w-3 h-3" /> Add Item
                        </Button>
                      )}
                    </td>
                  </tr>

                  {/* Line Items */}
                  {section.items?.map((item) => (
                    <tr key={item.id} className="border-b border-border last:border-0 hover:bg-muted/10 transition-colors">
                      <td className="py-2.5 px-4 font-medium text-foreground">
                        {item.description}
                        {item.remarks && <span className="block text-xs text-muted-foreground mt-0.5">{item.remarks}</span>}
                      </td>
                      <td className="py-2.5 px-4 text-center text-muted-foreground">{item.unit}</td>
                      <td className="py-2.5 px-4 text-right">{item.quantity}</td>
                      <td className="py-2.5 px-4 text-right">{formatCurrency(item.unit_rate)}</td>
                      <td className="py-2.5 px-4 text-right font-medium text-foreground">{formatCurrency(item.total)}</td>
                      <td className="py-2.5 px-4 text-center">
                        {selectedBoq.status === 'draft' && (
                          <button
                            onClick={() => deleteLineItemFromBOQ(selectedBoq.id, section.id, item.id)}
                            className="text-muted-foreground hover:text-destructive p-1 rounded transition-colors"
                            title="Delete Item"
                          >
                            <Trash2 className="w-3.5 h-3.5" />
                          </button>
                        )}
                      </td>
                    </tr>
                  ))}
                </React.Fragment>
              ))}
            </tbody>
          </table>
        </div>
      </Card>
      
      {/* Approval Status Banner */}
      {selectedBoq.status === 'approved' && (
        <div className="bg-green-50 border border-green-200 rounded-xl p-4 flex items-start gap-3">
          <div className="w-8 h-8 rounded-full bg-green-100 flex items-center justify-center flex-shrink-0">
            <Check className="w-4 h-4 text-green-600" />
          </div>
          <div>
            <p className="font-semibold text-green-800 text-sm">Digitally Approved by Client</p>
            <p className="text-green-700 text-xs mt-0.5">{selectedBoq.approved_at ? `Approved on ${formatDate(selectedBoq.approved_at)}` : "Approval recorded"}</p>
            {selectedBoq.approval_note && (
              <p className="text-green-800 text-sm mt-2 p-2 bg-green-100/60 rounded italic border-l-2 border-green-400">
                &ldquo;{selectedBoq.approval_note}&rdquo;
              </p>
            )}
          </div>
        </div>
      )}

      {selectedBoq.status === 'rejected' && (
        <div className="bg-red-50 border border-red-200 rounded-xl p-4 flex items-start gap-3">
          <div className="w-8 h-8 rounded-full bg-red-100 flex items-center justify-center flex-shrink-0">
            <X className="w-4 h-4 text-red-600" />
          </div>
          <div>
            <p className="font-semibold text-red-800 text-sm">Revision Requested by Client</p>
            <p className="text-red-700 text-xs mt-0.5">Client reason: {selectedBoq.approval_note || "Adjustments required"}</p>
            <Button size="sm" onClick={handleCreateNewVersion} className="mt-3 gap-1 bg-red-600 hover:bg-red-700 text-white border-0 text-xs">
              <Plus className="w-3.5 h-3.5" /> Create Revision v{selectedBoq.version_number + 1}
            </Button>
          </div>
        </div>
      )}

      {/* MODAL: Add Line Item */}
      <Dialog open={addItemModalOpen} onOpenChange={setAddItemModalOpen}>
        <DialogContent className="max-w-md">
          <DialogHeader>
            <DialogTitle>Add Line Item</DialogTitle>
          </DialogHeader>
          <form onSubmit={handleAddItemSubmit} className="space-y-4">
            {/* Quick Pick from Library */}
            <div className="p-3 bg-muted/40 rounded-lg space-y-2">
              <div className="flex items-center gap-1.5 text-xs font-semibold text-foreground">
                <BookOpen className="w-3.5 h-3.5 text-primary" /> Pick from Rate Master
              </div>
              <select 
                className="w-full text-xs p-2 rounded border border-input bg-card"
                onChange={(e) => {
                  const item = itemLibrary.find(i => i.id === e.target.value);
                  if (item) {
                    setNewItemForm({
                      ...newItemForm,
                      description: item.item_name || "",
                      unit: item.unit,
                      unit_rate: item.standard_rate || 0
                    });
                  }
                }}
                defaultValue=""
              >
                <option value="" disabled>Select from item library...</option>
                {itemLibrary.map(item => (
                  <option key={item.id} value={item.id}>
                    {item.item_name} ({item.unit} @ ₹{item.standard_rate})
                  </option>
                ))}
              </select>
            </div>

            <div className="space-y-1">
              <Label className="text-xs">Description</Label>
              <Input 
                required
                value={newItemForm.description}
                onChange={(e) => setNewItemForm({ ...newItemForm, description: e.target.value })}
                placeholder="e.g. 18mm Kalinga Stone Quartz Countertop"
              />
            </div>
            <div className="grid grid-cols-3 gap-3">
              <div className="space-y-1">
                <Label className="text-xs">Unit</Label>
                <select
                  value={newItemForm.unit}
                  onChange={(e) => setNewItemForm({ ...newItemForm, unit: e.target.value })}
                  className="w-full h-9 px-2 text-xs rounded border border-input bg-card"
                >
                  <option value="sqft">sqft</option>
                  <option value="RFT">RFT</option>
                  <option value="nos">nos</option>
                  <option value="lumpsum">lumpsum</option>
                </select>
              </div>
              <div className="space-y-1">
                <Label className="text-xs">Quantity</Label>
                <Input 
                  type="number"
                  min="0.1"
                  step="any"
                  required
                  value={newItemForm.quantity}
                  onChange={(e) => setNewItemForm({ ...newItemForm, quantity: parseFloat(e.target.value) || 0 })}
                />
              </div>
              <div className="space-y-1">
                <Label className="text-xs">Unit Rate (₹)</Label>
                <Input 
                  type="number"
                  min="0"
                  required
                  value={newItemForm.unit_rate}
                  onChange={(e) => setNewItemForm({ ...newItemForm, unit_rate: parseFloat(e.target.value) || 0 })}
                />
              </div>
            </div>
            <div className="space-y-1">
              <Label className="text-xs">Remarks (Optional)</Label>
              <Input 
                value={newItemForm.remarks}
                onChange={(e) => setNewItemForm({ ...newItemForm, remarks: e.target.value })}
                placeholder="e.g. Saint-Gobain 6mm toughened glass"
              />
            </div>
            <div className="p-2 bg-accent text-primary text-xs font-semibold rounded text-right">
              Total: {formatCurrency(newItemForm.quantity * newItemForm.unit_rate)}
            </div>
            <DialogFooter>
              <Button type="button" variant="outline" onClick={() => setAddItemModalOpen(false)}>Cancel</Button>
              <Button type="submit" className="gradient-primary border-0">Add Item</Button>
            </DialogFooter>
          </form>
        </DialogContent>
      </Dialog>

      {/* MODAL: Compare Versions */}
      <Dialog open={compareModalOpen} onOpenChange={setCompareModalOpen}>
        <DialogContent className="max-w-3xl">
          <DialogHeader>
            <DialogTitle>Compare BOQ Versions</DialogTitle>
          </DialogHeader>
          <div className="space-y-4">
            <div className="flex items-center justify-between p-3 bg-muted/40 rounded-lg">
              <div className="flex items-center gap-2">
                <span className="text-xs font-semibold">Comparing:</span>
                <span className="px-2 py-0.5 rounded bg-primary/10 text-primary text-xs font-bold">
                  v{selectedBoq.version_number} (Current)
                </span>
                <ArrowRight className="w-3.5 h-3.5 text-muted-foreground" />
                <select
                  value={compareVersionId}
                  onChange={(e) => setCompareVersionId(e.target.value)}
                  className="text-xs p-1.5 rounded border border-input bg-card font-medium"
                >
                  {boqVersions.filter(v => v.id !== selectedBoq.id).map(v => (
                    <option key={v.id} value={v.id}>
                      Version {v.version_number} ({v.version_label || v.status})
                    </option>
                  ))}
                </select>
              </div>

              <div className="text-right">
                <span className="text-xs text-muted-foreground">Net Cost Change: </span>
                <span className={cn("text-sm font-bold", netDifference > 0 ? "text-amber-600" : "text-emerald-600")}>
                  {netDifference > 0 ? `+${formatCurrency(netDifference)}` : formatCurrency(netDifference)}
                </span>
              </div>
            </div>

            {/* Diff Comparison Table */}
            <div className="border rounded-lg overflow-hidden max-h-80 overflow-y-auto">
              <table className="w-full text-xs">
                <thead className="bg-muted text-muted-foreground sticky top-0">
                  <tr>
                    <th className="p-2.5 text-left">Item Description</th>
                    <th className="p-2.5 text-right">v{compareTargetBoq.version_number} Total</th>
                    <th className="p-2.5 text-right">v{selectedBoq.version_number} Total</th>
                    <th className="p-2.5 text-right">Variance</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-border">
                  {selectedBoq.sections?.flatMap(s => s.items || []).map((item) => {
                    const oldItem = compareTargetBoq.sections?.flatMap(s => s.items || []).find(i => i.description === item.description);
                    const diff = item.total - (oldItem?.total || 0);
                    return (
                      <tr key={item.id} className={cn(
                        "hover:bg-muted/10",
                        !oldItem ? "bg-emerald-50/50" : diff !== 0 ? "bg-amber-50/50" : ""
                      )}>
                        <td className="p-2.5">
                          <span className="font-medium text-foreground">{item.description}</span>
                          {!oldItem && <span className="ml-2 text-[10px] text-emerald-600 font-bold uppercase">(Added)</span>}
                        </td>
                        <td className="p-2.5 text-right text-muted-foreground">
                          {oldItem ? formatCurrency(oldItem.total) : "—"}
                        </td>
                        <td className="p-2.5 text-right font-medium">
                          {formatCurrency(item.total)}
                        </td>
                        <td className={cn("p-2.5 text-right font-semibold", diff > 0 ? "text-amber-600" : diff < 0 ? "text-emerald-600" : "text-muted-foreground")}>
                          {diff > 0 ? `+${formatCurrency(diff)}` : diff < 0 ? formatCurrency(diff) : "0"}
                        </td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>
          </div>
          <DialogFooter>
            <Button onClick={() => setCompareModalOpen(false)}>Close</Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* MODAL: Export PDF Branded Preview */}
      <Dialog open={exportModalOpen} onOpenChange={setExportModalOpen}>
        <DialogContent className="max-w-2xl">
          <DialogHeader>
            <DialogTitle>BOQ Export Preview</DialogTitle>
          </DialogHeader>
          <div className="p-6 bg-white text-slate-800 rounded-lg border border-slate-200 shadow-sm space-y-4 print:p-0">
            {/* Document Header */}
            <div className="flex justify-between items-start border-b pb-4">
              <div>
                <h2 className="text-xl font-bold text-slate-900">{studioSettings.name}</h2>
                <p className="text-xs text-slate-500">{studioSettings.tagline}</p>
                <p className="text-xs text-slate-500 mt-1">{studioSettings.address}</p>
                <p className="text-xs text-slate-500">GST: {studioSettings.gstin || "—"}</p>
              </div>
              <div className="text-right">
                <span className="px-2 py-0.5 rounded text-xs font-bold bg-slate-100 uppercase">
                  BOQ v{selectedBoq.version_number}
                </span>
                <p className="text-xs text-slate-500 mt-2">Date: {formatDate(selectedBoq.created_at)}</p>
                <p className="text-xs font-semibold text-slate-700">Status: {selectedBoq.status.toUpperCase()}</p>
              </div>
            </div>

            {/* Sections summary */}
            <div className="space-y-3">
              <h3 className="text-xs font-bold uppercase tracking-wider text-slate-500">Scope of Work & Quantities</h3>
              <table className="w-full text-xs">
                <thead>
                  <tr className="border-b bg-slate-50">
                    <th className="p-2 text-left">Item</th>
                    <th className="p-2 text-center">Unit</th>
                    <th className="p-2 text-right">Qty</th>
                    <th className="p-2 text-right">Rate</th>
                    <th className="p-2 text-right">Amount</th>
                  </tr>
                </thead>
                <tbody className="divide-y">
                  {selectedBoq.sections?.flatMap(s => s.items || []).map((it) => (
                    <tr key={it.id}>
                      <td className="p-2">{it.description}</td>
                      <td className="p-2 text-center">{it.unit}</td>
                      <td className="p-2 text-right">{it.quantity}</td>
                      <td className="p-2 text-right">{formatCurrency(it.unit_rate)}</td>
                      <td className="p-2 text-right font-medium">{formatCurrency(it.total)}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>

            {/* Financial Totals */}
            <div className="flex justify-end pt-3 border-t">
              <div className="w-56 text-xs space-y-1.5">
                <div className="flex justify-between">
                  <span className="text-slate-500">Subtotal:</span>
                  <span className="font-medium">{formatCurrency(selectedBoq.sections?.reduce((s, x) => s + x.subtotal, 0) || 0)}</span>
                </div>
                <div className="flex justify-between">
                  <span className="text-slate-500">GST ({selectedBoq.gst_percent || 18}%):</span>
                  <span className="font-medium">{formatCurrency(((selectedBoq.sections?.reduce((s, x) => s + x.subtotal, 0) || 0) * (selectedBoq.gst_percent || 18)) / 100)}</span>
                </div>
                <div className="flex justify-between">
                  <span className="text-slate-500">Designer Fee:</span>
                  <span className="font-medium">{formatCurrency(selectedBoq.designer_fee || 0)}</span>
                </div>
                <div className="flex justify-between text-sm font-bold border-t pt-1.5 text-slate-900">
                  <span>Grand Total:</span>
                  <span>{formatCurrency(selectedBoq.grand_total)}</span>
                </div>
              </div>
            </div>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setExportModalOpen(false)}>Close</Button>
            <Button onClick={() => window.print()} className="gap-2 gradient-primary border-0">
              <Printer className="w-4 h-4" /> Print / Save PDF
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

"use client";

import { useState } from "react";
import { Card, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Label } from "@/components/ui/label";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from "@/components/ui/dialog";
import { Upload, FileText, Trash2, Eye, EyeOff } from "lucide-react";
import { useAppStore } from "@/lib/store";
import { formatDate, formatFileSize, cn } from "@/lib/utils";
import { uploadToProject } from "@/lib/supabase/upload";
import { toast } from "@/components/ui/toast";
import type { Project, ProjectFile } from "@/types";

export default function FilesTab({ project, files }: { project: Project; files: ProjectFile[] }) {
  const { addFile, toggleFileVisibility, deleteFile } = useAppStore();

  const [uploadFileModalOpen, setUploadFileModalOpen] = useState(false);
  const [fileForm, setFileForm] = useState({
    file: null as File | null,
    folder: "Drawings & Layouts",
    isClientVisible: false,
  });
  const [uploading, setUploading] = useState(false);
  const [selectedFolderFilter, setSelectedFolderFilter] = useState("all");

  const handleUploadFile = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!fileForm.file) return;
    setUploading(true);
    try {
      const storage_path = await uploadToProject(project.id, fileForm.file);
      const r = await addFile({
        project_id: project.id,
        folder: fileForm.folder,
        file_name: fileForm.file.name,
        storage_path,
        file_type: fileForm.file.type || "application/octet-stream",
        file_size_bytes: fileForm.file.size,
        is_client_visible: fileForm.isClientVisible,
      });
      if (r.ok) {
        setFileForm({ file: null, folder: "Drawings & Layouts", isClientVisible: false });
        setUploadFileModalOpen(false);
      }
    } catch (err) {
      toast.add({ title: "Upload failed", description: (err as Error).message, type: "error" });
    } finally {
      setUploading(false);
    }
  };

  return (
    <>
      <div className="flex flex-wrap items-center justify-between gap-3">
        <div className="flex flex-wrap gap-1.5">
          {["all", "Contracts", "BOQ & Quotations", "Drawings & Layouts", "3D Renders", "Site Photos", "Material Selections"].map((fld) => (
            <Button
              key={fld}
              variant={selectedFolderFilter === fld ? "default" : "outline"}
              size="sm"
              onClick={() => setSelectedFolderFilter(fld)}
              className="text-xs h-7"
            >
              {fld}
            </Button>
          ))}
        </div>
        <Button size="sm" onClick={() => setUploadFileModalOpen(true)} className="gradient-primary border-0 gap-1.5 text-xs">
          <Upload className="w-3.5 h-3.5" /> Upload File
        </Button>
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-4">
        {files
          .filter(f => selectedFolderFilter === 'all' || f.folder === selectedFolderFilter)
          .map((file) => (
            <Card key={file.id} className="card-hover overflow-hidden">
              <a href={file.file_url} target="_blank" rel="noreferrer" className="block">
                {file.file_type.includes('image') ? (
                  <div className="h-32 bg-muted overflow-hidden relative">
                    <img src={file.file_url} alt={file.file_name} className="w-full h-full object-cover" />
                    <span className="absolute top-1 right-1 bg-black/60 text-white text-[9px] px-1.5 py-0.5 rounded">
                      {file.folder}
                    </span>
                  </div>
                ) : (
                  <div className="h-32 bg-accent/60 flex flex-col items-center justify-center p-3 relative">
                    <FileText className="w-10 h-10 text-primary mb-2" />
                    <span className="text-[10px] font-bold text-primary uppercase">{file.file_type.split('/')[1] || 'DOC'}</span>
                    <span className="absolute top-1 right-1 bg-muted text-muted-foreground text-[9px] px-1.5 py-0.5 rounded">
                      {file.folder}
                    </span>
                  </div>
                )}
              </a>
              <CardContent className="p-3">
                <a href={file.file_url} target="_blank" rel="noreferrer" className="block hover:underline">
                  <p className="text-xs font-semibold text-foreground truncate mb-1" title={file.file_name}>
                    {file.file_name}
                  </p>
                </a>
                <div className="flex items-center justify-between text-[10px] text-muted-foreground mb-2">
                  <span>{formatFileSize(file.file_size_bytes || 0)}</span>
                  <span>{formatDate(file.created_at)}</span>
                </div>
                <div className="flex items-center justify-between pt-2 border-t">
                  <button
                    onClick={() => toggleFileVisibility(file.id)}
                    className={cn("flex items-center gap-1 text-[10px] font-medium transition-colors", file.is_client_visible ? "text-emerald-600" : "text-muted-foreground")}
                  >
                    {file.is_client_visible ? <Eye className="w-3 h-3" /> : <EyeOff className="w-3 h-3" />}
                    {file.is_client_visible ? "Client Visible" : "Studio Only"}
                  </button>
                  <button 
                    onClick={() => {
                      if (window.confirm(`Delete ${file.file_name}?`)) {
                        deleteFile(file.id);
                      }
                    }}
                    className="text-muted-foreground hover:text-destructive p-1"
                  >
                    <Trash2 className="w-3.5 h-3.5" />
                  </button>
                </div>
              </CardContent>
            </Card>
          ))}
      </div>

      {/* MODAL: Upload File */}
      <Dialog open={uploadFileModalOpen} onOpenChange={setUploadFileModalOpen}>
        <DialogContent className="max-w-md">
          <DialogHeader>
            <DialogTitle>Upload File to Project</DialogTitle>
          </DialogHeader>
          <form onSubmit={handleUploadFile} className="space-y-3">
            <div className="space-y-1">
              <Label className="text-xs">Choose File</Label>
              <input
                type="file"
                required
                onChange={(e) => setFileForm({ ...fileForm, file: e.target.files?.[0] ?? null })}
                className="mt-1 block w-full text-xs"
              />
            </div>
            <div className="space-y-1">
              <Label className="text-xs">Folder Category</Label>
              <select
                value={fileForm.folder}
                onChange={(e) => setFileForm({ ...fileForm, folder: e.target.value })}
                className="w-full h-9 px-2 text-xs rounded border border-input bg-card"
              >
                {["Contracts", "BOQ & Quotations", "Drawings & Layouts", "3D Renders", "Site Photos", "Material Selections", "Invoices", "Miscellaneous"].map(f => (
                  <option key={f} value={f}>{f}</option>
                ))}
              </select>
            </div>
            <div className="flex items-center gap-2 pt-2">
              <input
                type="checkbox"
                id="isClientVis"
                checked={fileForm.isClientVisible}
                onChange={(e) => setFileForm({ ...fileForm, isClientVisible: e.target.checked })}
                className="rounded"
              />
              <Label htmlFor="isClientVis" className="text-xs font-normal cursor-pointer">Make visible to client on their portal</Label>
            </div>
            <DialogFooter>
              <Button type="button" variant="outline" onClick={() => setUploadFileModalOpen(false)}>Cancel</Button>
              <Button type="submit" disabled={uploading || !fileForm.file} className="gradient-primary border-0">
                {uploading ? "Uploading…" : "Upload"}
              </Button>
            </DialogFooter>
          </form>
        </DialogContent>
      </Dialog>
    </>
  );
}

"use client";

import { Card, CardContent } from "@/components/ui/card";
import { Check, Palette } from "lucide-react";
import { useAppStore } from "@/lib/store";
import { cn } from "@/lib/utils";
import type { MaterialOption } from "@/types";

export default function MaterialsTab({ materials }: { materials: MaterialOption[] }) {
  const { toggleMaterialSelection } = useAppStore();

  return (
    <>
      <div className="flex justify-between items-center">
        <span className="text-xs font-bold uppercase tracking-wider text-muted-foreground">Material Selections & Specifications</span>
      </div>

      {materials.length > 0 ? (
        <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 gap-4">
          {materials.map(mat => (
            <Card key={mat.id} className="overflow-hidden card-hover">
              <div className="h-44 bg-muted overflow-hidden relative">
                <img src={mat.image_url} alt={mat.product_name} className="w-full h-full object-cover" />
                <span className="absolute top-2 right-2 bg-black/60 text-white text-[10px] px-2 py-0.5 rounded font-bold">
                  {mat.category}
                </span>
              </div>
              <CardContent className="p-4 space-y-2">
                <div className="flex justify-between items-start">
                  <h4 className="font-bold text-xs text-foreground leading-snug">{mat.product_name}</h4>
                  <span className="text-xs font-bold text-primary">₹{mat.approx_cost}</span>
                </div>
                <p className="text-[11px] text-muted-foreground">{mat.brand} · {mat.room_name}</p>
                <p className="text-[11px] text-muted-foreground line-clamp-2">{mat.description}</p>
                <div className="pt-2 border-t flex justify-between items-center">
                  <button
                    onClick={() => toggleMaterialSelection(mat.id)}
                    className={cn(
                      "px-2.5 py-1 rounded text-xs font-semibold flex items-center gap-1.5 transition-all",
                      mat.is_selected ? "bg-emerald-100 text-emerald-800" : "bg-muted text-muted-foreground hover:bg-muted/80"
                    )}
                  >
                    <Check className="w-3 h-3" />
                    {mat.is_selected ? "Selected by Client" : "Select Option"}
                  </button>
                </div>
              </CardContent>
            </Card>
          ))}
        </div>
      ) : (
        <div className="flex flex-col items-center justify-center py-20 text-center border-2 border-dashed border-border rounded-xl bg-slate-50/50">
          <div className="w-16 h-16 rounded-full bg-slate-100 flex items-center justify-center mb-4">
            <Palette className="w-8 h-8 text-slate-400" />
          </div>
          <h3 className="text-lg font-semibold text-foreground mb-1">No Materials Selected</h3>
          <p className="text-sm text-muted-foreground max-w-sm mx-auto mb-6">
            You haven&apos;t added any material options or moodboard items for this project yet.
          </p>
          <p className="max-w-sm text-xs text-muted-foreground">Material selection will be available here when options are added to this project.</p>
        </div>
      )}
    </>
  );
}

"use client";

import { useState, useRef } from "react";
import { Message } from "@/types";
import { Card } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { Avatar, AvatarFallback } from "@/components/ui/avatar";
import { formatDateTime, getInitials, cn } from "@/lib/utils";
import { Paperclip, Send, Check, MessageSquare, Image as ImageIcon } from "lucide-react";

import { useAppStore } from "@/lib/store";

export default function MessagesTab({ projectId, messages }: { projectId: string; messages: Message[] }) {
  const [newMessage, setNewMessage] = useState("");
  const fileInputRef = useRef<HTMLInputElement>(null);
  const { addMessage, me } = useAppStore();

  const handleSend = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newMessage.trim()) return;
    addMessage({
      project_id: projectId,
      content: newMessage.trim(),
    });
    setNewMessage("");
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const fileUrl = URL.createObjectURL(file);
    
    addMessage({
      project_id: projectId,
      content: "",
      file_url: fileUrl,
      file_name: file.name,
    });
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  // Group messages by date would go here in a real app, for now just a list
  
  return (
    <Card className="flex flex-col h-[600px] border-border overflow-hidden">
      {/* Chat messages area */}
      <div className="flex-1 overflow-y-auto p-4 space-y-4 bg-slate-50/50">
        {messages.map((msg) => {
          const isMe = msg.sender_id === me.id;
          return (
            <div key={msg.id} className={cn("flex w-full", isMe ? "justify-end" : "justify-start")}>
              <div className={cn("flex max-w-[75%] gap-2", isMe ? "flex-row-reverse" : "flex-row")}>
                
                <Avatar className="w-8 h-8 flex-shrink-0 mt-auto">
                  <AvatarFallback className={cn("text-[10px] font-bold", isMe ? "bg-primary/10 text-primary" : "bg-slate-200 text-slate-700")}>
                    {getInitials(msg.sender_name)}
                  </AvatarFallback>
                </Avatar>

                <div className="flex flex-col gap-1">
                  <span className={cn("text-[10px] text-muted-foreground px-1", isMe ? "text-right" : "text-left")}>
                    {msg.sender_name}
                  </span>
                  
                  <div className={cn(
                    "px-4 py-2.5 shadow-sm text-sm",
                    isMe ? "message-bubble-right" : "message-bubble-left border border-border"
                  )}>
                    {msg.content && <p>{msg.content}</p>}
                    {msg.file_url && (
                      <div className="mt-2 mb-1 rounded-md overflow-hidden max-w-[200px] border border-black/10">
                        <img src={msg.file_url} alt="Attachment" className="w-full h-auto object-cover block" />
                      </div>
                    )}
                  </div>
                  
                  <div className={cn("flex items-center gap-1 text-[10px] text-muted-foreground px-1 mt-0.5", isMe ? "justify-end" : "justify-start")}>
                    {formatDateTime(msg.created_at)}
                    {isMe && <Check className="w-3 h-3" />}
                  </div>
                </div>
              </div>
            </div>
          );
        })}

        {messages.length === 0 && (
          <div className="flex flex-col items-center justify-center h-full text-center text-muted-foreground space-y-3 opacity-60 mt-10">
            <div className="w-16 h-16 rounded-full bg-muted flex items-center justify-center mb-2">
              <MessageSquare className="w-8 h-8" />
            </div>
            <p className="text-sm font-medium text-foreground">No messages yet</p>
            <p className="text-xs max-w-xs">Send a message to start the conversation with the client.</p>
          </div>
        )}
      </div>

      {/* Input area */}
      <div className="p-3 border-t border-border bg-card">
        <form onSubmit={handleSend} className="flex items-center gap-2">
          <input 
            type="file" 
            ref={fileInputRef} 
            className="hidden" 
            accept="image/*"
            onChange={handleFileUpload} 
          />
          <Button 
            type="button" 
            variant="ghost" 
            size="icon" 
            className="text-muted-foreground hover:text-foreground"
            onClick={() => fileInputRef.current?.click()}
          >
            <Paperclip className="w-5 h-5" />
          </Button>
          <Input
            value={newMessage}
            onChange={(e) => setNewMessage(e.target.value)}
            placeholder="Type a message..."
            className="flex-1 bg-muted/50 border-transparent focus-visible:ring-1 focus-visible:ring-primary focus-visible:border-primary focus-visible:bg-background transition-all"
          />
          <Button type="submit" disabled={!newMessage.trim()} className="gradient-primary border-0 rounded-full w-10 h-10 p-0 flex items-center justify-center">
            <Send className="w-4 h-4 ml-0.5" />
          </Button>
        </form>
      </div>
    </Card>
  );
}

"use client";

import React, { useState } from "react";
import { Snag, ProjectRoom, SnagStatus, SnagPriority } from "@/types";
import { Card, CardContent } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Progress } from "@/components/ui/progress";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from "@/components/ui/dialog";
import { Avatar, AvatarFallback } from "@/components/ui/avatar";
import { formatRelativeTime, formatDate, formatShortDate, getStatusColor, getPriorityColor, getInitials, cn } from "@/lib/utils";
import { AlertCircle, Camera, Check, Clock, Plus, ArrowRight, MessageSquare, ShieldCheck, Printer, CheckCircle2 } from "lucide-react";
import { useAppStore } from "@/lib/store";
import { AssigneeSelect } from "@/components/team/AssigneeSelect";
import { PhotoInput } from "@/components/files/PhotoInput";

export default function SnagTab({ projectId, snags, rooms }: { projectId: string; snags: Snag[]; rooms: ProjectRoom[] }) {
  const { addSnag, updateSnagStatus, assignSnagVendor, addSnagComment, studioSettings, projects, me, team, vendors } = useAppStore();
  const leadDesigner = team.find(m => m.id === project?.director_id) ?? team.find(m => m.roles.includes("architect") || m.roles.includes("owner"));
  const project = projects.find(p => p.id === projectId);

  const [filter, setFilter] = useState<"all" | "open" | "closed">("all");
  const [raiseModalOpen, setRaiseModalOpen] = useState(false);
  const [selectedSnagId, setSelectedSnagId] = useState<string | null>(null);
  const selectedSnag = snags.find((s) => s.id === selectedSnagId) ?? null;
  const [afterPhotoPath, setAfterPhotoPath] = useState("");
  const [handoverModalOpen, setHandoverModalOpen] = useState(false);

  // Form for raising snag
  const [newSnagForm, setNewSnagForm] = useState({
    title: "",
    description: "",
    room_id: rooms[0]?.id || "",
    location_detail: "",
    priority: "major" as SnagPriority,
    assigned_to: "",
    vendor_id: "",
    due_date: "",
    before_photo_url: ""
  });

  // State for adding a comment
  const [commentText, setCommentText] = useState("");

  const filteredSnags = snags.filter((s) => {
    if (filter === "open") return s.status !== "closed";
    if (filter === "closed") return s.status === "closed";
    return true;
  });

  const completionPercent = snags.length ? Math.round((snags.filter(s => s.status === "closed").length / snags.length) * 100) : 0;
  const isHandoverBlocked = completionPercent < 100;

  const handleRaiseSnagSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    addSnag({
      project_id: projectId,
      room_id: newSnagForm.room_id || undefined,
      title: newSnagForm.title,
      description: newSnagForm.description,
      location_detail: newSnagForm.location_detail,
      priority: newSnagForm.priority,
      assigned_to: newSnagForm.assigned_to || undefined,
      vendor_id: newSnagForm.vendor_id || undefined,
      due_date: newSnagForm.due_date || undefined,
      before_photo_url: newSnagForm.before_photo_url || undefined,
    });
    setRaiseModalOpen(false);
    setNewSnagForm({
      title: "",
      description: "",
      room_id: rooms[0]?.id || "",
      location_detail: "",
      priority: "major",
      assigned_to: "",
      vendor_id: "",
      due_date: "",
      before_photo_url: "",
    });
  };

  const handleStatusChange = (snag: Snag, nextStatus: SnagStatus) => {
    updateSnagStatus(snag.id, nextStatus, undefined, nextStatus === "fixed" ? afterPhotoPath || undefined : undefined);
  };

  const handleAddComment = (e: React.FormEvent) => {
    e.preventDefault();
    if (!commentText.trim() || !selectedSnag) return;
    addSnagComment(selectedSnag.id, {
      author_id: me.id,
      author_name: me.full_name,
      content: commentText
    });
    setCommentText("");
  };

  return (
    <div className="space-y-6">
      {/* Stats & Filters */}
      <div className="flex flex-wrap items-center justify-between gap-4">
        <div className="flex flex-wrap items-center gap-4 bg-card border border-border rounded-xl px-4 py-2.5">
          <div className="flex items-center gap-3">
            <span className="text-sm font-semibold">Completion: {completionPercent}%</span>
            <Progress value={completionPercent} className="h-2 w-28" />
          </div>
          <div className="hidden sm:block w-px h-6 bg-border" />
          <div className="flex items-center gap-4 text-xs text-muted-foreground">
            <span><strong className="text-foreground">{snags.length}</strong> Total</span>
            <span><strong className="text-amber-600">{snags.filter(s => s.status !== 'closed').length}</strong> Open</span>
            <span><strong className="text-green-600">{snags.filter(s => s.status === 'closed').length}</strong> Closed</span>
          </div>
          {isHandoverBlocked && snags.length > 0 ? (
            <>
              <div className="hidden sm:block w-px h-6 bg-border" />
              <Badge variant="destructive" className="gap-1 text-[10px]">
                <AlertCircle className="w-3 h-3" /> Handover Blocked
              </Badge>
            </>
          ) : snags.length > 0 ? (
            <>
              <div className="hidden sm:block w-px h-6 bg-border" />
              <Badge className="bg-emerald-100 text-emerald-800 border-0 gap-1 text-[10px]">
                <ShieldCheck className="w-3 h-3" /> Ready for Handover
              </Badge>
            </>
          ) : null}
        </div>

        <div className="flex items-center gap-2">
          <Button 
            variant="outline" 
            size="sm" 
            onClick={() => setHandoverModalOpen(true)}
            className="text-xs gap-1.5"
          >
            <ShieldCheck className="w-3.5 h-3.5 text-primary" /> Handover Report
          </Button>

          <div className="flex rounded-lg border border-border overflow-hidden p-0.5 bg-card">
            {(["all", "open", "closed"] as const).map((f) => (
              <button
                key={f}
                onClick={() => setFilter(f)}
                className={cn("px-2.5 py-1 text-xs font-medium rounded-md capitalize transition-colors", filter === f ? "bg-muted text-foreground" : "text-muted-foreground hover:bg-muted/50")}
              >
                {f}
              </button>
            ))}
          </div>

          <Button size="sm" onClick={() => setRaiseModalOpen(true)} className="gradient-primary border-0 gap-1.5 text-xs">
            <Plus className="w-3.5 h-3.5" /> Raise Snag
          </Button>
        </div>
      </div>

      {/* Snag Grid Cards */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
        {filteredSnags.map((snag) => (
          <Card 
            key={snag.id} 
            onClick={() => setSelectedSnagId(snag.id)} 
            className="card-hover cursor-pointer border-border hover:border-primary/50 transition-all"
          >
            <CardContent className="p-4 flex gap-4">
              {/* Photo thumbnail */}
              <div className="w-24 h-24 rounded-lg overflow-hidden flex-shrink-0 bg-muted border border-border relative">
                {snag.before_photo_url ? (
                  <img src={snag.before_photo_url} alt={snag.title} className="w-full h-full object-cover" />
                ) : (
                  <div className="w-full h-full flex flex-col items-center justify-center text-muted-foreground">
                    <Camera className="w-6 h-6 mb-1 opacity-40" />
                    <span className="text-[10px]">No photo</span>
                  </div>
                )}
                {snag.after_photo_url && (
                  <span className="absolute bottom-1 right-1 bg-green-600 text-white text-[9px] px-1 py-0.2 rounded font-bold">
                    FIXED
                  </span>
                )}
              </div>
              
              <div className="flex-1 min-w-0 flex flex-col">
                <div className="flex items-start justify-between gap-2 mb-1">
                  <h4 className="font-semibold text-sm text-foreground truncate">{snag.title}</h4>
                  <Badge className={cn("text-[10px] px-1.5 py-0 border-0 uppercase flex-shrink-0", getStatusColor(snag.status))}>
                    {snag.status.replace('_', ' ')}
                  </Badge>
                </div>
                
                <p className="text-xs text-muted-foreground mb-3 flex items-center gap-1.5 truncate">
                  <span className="font-medium text-foreground">{snag.room_name}</span>
                  <span className="text-[10px]">·</span>
                  <span className="truncate">{snag.location_detail}</span>
                  {snag.vendor_name && <span className="text-primary truncate">· {snag.vendor_name}</span>}
                </p>

                <div className="mt-auto flex items-center justify-between">
                  <div className="flex items-center gap-2">
                    <Avatar className="w-6 h-6 border border-border">
                      <AvatarFallback className="text-[10px] bg-slate-100 font-semibold">{getInitials(snag.assigned_to_name || 'Unassigned')}</AvatarFallback>
                    </Avatar>
                    <span className="text-xs font-medium truncate max-w-[100px]">
                      {snag.assigned_to_name || 'Unassigned'}
                    </span>
                  </div>
                  
                  <div className="flex items-center gap-2">
                    <span className={cn("text-[10px] px-1.5 py-0.5 rounded font-medium border", getPriorityColor(snag.priority))}>
                      {snag.priority}
                    </span>
                    {snag.due_date && (
                      <span className="text-[10px] text-muted-foreground flex items-center gap-1">
                        <Clock className="w-3 h-3" />
                        {formatShortDate(snag.due_date)}
                      </span>
                    )}
                  </div>
                </div>
              </div>
            </CardContent>
          </Card>
        ))}

        {filteredSnags.length === 0 && (
          <div className="col-span-full py-12 text-center text-muted-foreground border-2 border-dashed border-border rounded-xl">
            <Check className="w-8 h-8 mx-auto mb-2 text-green-500 opacity-50" />
            <p className="font-medium text-sm">No {filter !== 'all' ? filter : ''} snags found</p>
          </div>
        )}
      </div>

      {/* MODAL: Raise Snag */}
      <Dialog open={raiseModalOpen} onOpenChange={setRaiseModalOpen}>
        <DialogContent className="max-w-md">
          <DialogHeader>
            <DialogTitle>Raise New Snag</DialogTitle>
          </DialogHeader>
          <form onSubmit={handleRaiseSnagSubmit} className="space-y-3">
            <div className="space-y-1">
              <Label className="text-xs">Snag Title</Label>
              <Input 
                required 
                value={newSnagForm.title} 
                onChange={(e) => setNewSnagForm({ ...newSnagForm, title: e.target.value })}
                placeholder="e.g. Tile grout crack near shower enclosure"
              />
            </div>
            <div className="grid grid-cols-2 gap-3">
              <div className="space-y-1">
                <Label className="text-xs">Room / Area</Label>
                <select
                  value={newSnagForm.room_id}
                  onChange={(e) => setNewSnagForm({ ...newSnagForm, room_id: e.target.value })}
                  className="w-full h-9 px-2 text-xs rounded border border-input bg-card"
                >
                  {rooms.map(r => (
                    <option key={r.id} value={r.id}>{r.name}</option>
                  ))}
                </select>
              </div>
              <div className="space-y-1">
                <Label className="text-xs">Priority</Label>
                <select
                  value={newSnagForm.priority}
                  onChange={(e) => setNewSnagForm({ ...newSnagForm, priority: e.target.value as SnagPriority })}
                  className="w-full h-9 px-2 text-xs rounded border border-input bg-card"
                >
                  <option value="critical">Critical 🔴</option>
                  <option value="major">Major 🟡</option>
                  <option value="minor">Minor 🟢</option>
                </select>
              </div>
            </div>
            <div className="space-y-1">
              <Label className="text-xs">Specific Location Detail</Label>
              <Input 
                value={newSnagForm.location_detail} 
                onChange={(e) => setNewSnagForm({ ...newSnagForm, location_detail: e.target.value })}
                placeholder="e.g. Master toilet east wall, 2ft above skirting"
              />
            </div>
            <div className="grid grid-cols-2 gap-3">
              <div className="space-y-1">
                <Label className="text-xs">Assignee</Label>
                <AssigneeSelect 
                  value={newSnagForm.assigned_to} 
                  onChange={(v) => setNewSnagForm({ ...newSnagForm, assigned_to: v })} 
                />
              </div>
              <div className="space-y-1">
                <Label className="text-xs">Rectification Due Date</Label>
                <Input 
                  type="date"
                  value={newSnagForm.due_date} 
                  onChange={(e) => setNewSnagForm({ ...newSnagForm, due_date: e.target.value })}
                />
              </div>
            </div>
            <div className="space-y-1">
              <Label className="text-xs">Responsible vendor/contractor</Label>
              <select
                value={newSnagForm.vendor_id}
                onChange={(e) => setNewSnagForm({ ...newSnagForm, vendor_id: e.target.value })}
                className="w-full h-9 px-2 text-xs rounded border border-input bg-card"
              >
                <option value="">None</option>
                {vendors.filter((v) => v.status !== "blacklisted").map((v) => (
                  <option key={v.id} value={v.id}>{v.name} ({v.category})</option>
                ))}
              </select>
            </div>
            <div className="space-y-1">
              <PhotoInput 
                projectId={projectId} 
                label="Before photo" 
                onUploaded={(p) => setNewSnagForm({ ...newSnagForm, before_photo_url: p })} 
              />
            </div>
            <div className="space-y-1">
              <Label className="text-xs">Detailed Description</Label>
              <Textarea 
                value={newSnagForm.description} 
                onChange={(e) => setNewSnagForm({ ...newSnagForm, description: e.target.value })}
                placeholder="Detailed explanation of the issue to be fixed..."
                rows={2}
              />
            </div>
            <DialogFooter>
              <Button type="button" variant="outline" onClick={() => setRaiseModalOpen(false)}>Cancel</Button>
              <Button type="submit" className="gradient-primary border-0">Submit Snag</Button>
            </DialogFooter>
          </form>
        </DialogContent>
      </Dialog>

      {/* MODAL: Snag Detail & Status Progression */}
      {selectedSnag && (
        <Dialog open={!!selectedSnag} onOpenChange={() => setSelectedSnagId(null)}>
          <DialogContent className="max-w-2xl">
            <DialogHeader>
              <div className="flex items-center justify-between">
                <DialogTitle className="text-base font-bold">{selectedSnag.title}</DialogTitle>
                <Badge className={cn("border-0 uppercase text-[10px]", getStatusColor(selectedSnag.status))}>
                  {selectedSnag.status.replace('_', ' ')}
                </Badge>
              </div>
            </DialogHeader>

            <div className="space-y-4">
              {/* Status Progression Bar */}
              <div className="p-3 bg-muted/40 rounded-xl">
                <p className="text-[11px] font-semibold text-muted-foreground uppercase tracking-wider mb-2">
                  Workflow Progression
                </p>
                <div className="flex items-center justify-between text-xs">
                  {(['raised', 'assigned', 'in_progress', 'fixed', 'verified', 'closed'] as SnagStatus[]).map((st, i, arr) => {
                    const isPassed = arr.indexOf(selectedSnag.status) >= i;
                    const isCurrent = selectedSnag.status === st;
                    return (
                      <div key={st} className="flex items-center gap-1.5">
                        <div className={cn(
                          "w-5 h-5 rounded-full flex items-center justify-center text-[10px] font-bold transition-all",
                          isCurrent ? "bg-primary text-white scale-110 shadow" :
                          isPassed ? "bg-green-100 text-green-700" : "bg-muted text-muted-foreground"
                        )}>
                          {isPassed ? "✓" : i + 1}
                        </div>
                        <span className={cn("capitalize hidden sm:inline text-[11px]", isCurrent ? "font-bold text-foreground" : "text-muted-foreground")}>
                          {st.replace('_', ' ')}
                        </span>
                        {i < arr.length - 1 && <ArrowRight className="w-3 h-3 text-muted-foreground/40 hidden sm:inline" />}
                      </div>
                    );
                  })}
                </div>
              </div>

              {/* Before & After Photo Comparison */}
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1.5">
                  <span className="text-xs font-semibold text-foreground">Before Photo (Raised)</span>
                  <div className="h-44 rounded-lg bg-muted overflow-hidden border border-border">
                    {selectedSnag.before_photo_url ? (
                      <img src={selectedSnag.before_photo_url} alt="Before" className="w-full h-full object-cover" />
                    ) : (
                      <div className="w-full h-full flex items-center justify-center text-muted-foreground text-xs">No Before Photo</div>
                    )}
                  </div>
                </div>

                <div className="space-y-1.5">
                  <span className="text-xs font-semibold text-foreground">After Photo (Rectified)</span>
                  <div className="h-44 rounded-lg bg-muted overflow-hidden border border-border relative">
                    {selectedSnag.after_photo_url ? (
                      <img src={selectedSnag.after_photo_url} alt="After" className="w-full h-full object-cover" />
                    ) : (
                      <div className="w-full h-full flex flex-col items-center justify-center text-muted-foreground text-xs p-4 text-center">
                        <Camera className="w-6 h-6 mb-1 opacity-40" />
                        <span>Awaiting rectification photo from contractor</span>
                      </div>
                    )}
                  </div>
                </div>
              </div>

              <div className="space-y-1">
                <PhotoInput projectId={projectId} label="After photo" onUploaded={setAfterPhotoPath} />
              </div>

              <div className="space-y-1">
                <Label className="text-xs">Responsible vendor/contractor</Label>
                <select
                  value={selectedSnag.vendor_id || ""}
                  onChange={(e) => assignSnagVendor(selectedSnag.id, e.target.value || null)}
                  className="w-full h-9 px-2 text-xs rounded border border-input bg-card"
                >
                  <option value="">None</option>
                  {vendors.filter((v) => v.status !== "blacklisted").map((v) => (
                    <option key={v.id} value={v.id}>{v.name} ({v.category})</option>
                  ))}
                </select>
              </div>

              {/* Action Buttons for advancing status */}
              <div className="flex flex-wrap items-center justify-between p-3 bg-muted/20 border rounded-lg gap-2">
                <span className="text-xs text-muted-foreground">Quick Action Controls:</span>
                <div className="flex flex-wrap items-center gap-2">
                  {selectedSnag.status === 'raised' && (
                    <Button size="sm" onClick={() => handleStatusChange(selectedSnag, 'assigned')} className="text-xs">
                      Assign to Vendor
                    </Button>
                  )}
                  {selectedSnag.status === 'assigned' && (
                    <Button size="sm" onClick={() => handleStatusChange(selectedSnag, 'in_progress')} className="text-xs">
                      Start Progress
                    </Button>
                  )}
                  {selectedSnag.status === 'in_progress' && (
                    <Button size="sm" onClick={() => handleStatusChange(selectedSnag, 'fixed')} className="text-xs bg-amber-600 hover:bg-amber-700 text-white border-0">
                      Mark as Fixed (Attach After Photo)
                    </Button>
                  )}
                  {selectedSnag.status === 'fixed' && (
                    <Button size="sm" onClick={() => handleStatusChange(selectedSnag, 'verified')} className="text-xs bg-primary hover:bg-primary/90 text-white border-0">
                      Verify Fix (Designer Sign-off)
                    </Button>
                  )}
                  {selectedSnag.status === 'verified' && (
                    <Button size="sm" onClick={() => handleStatusChange(selectedSnag, 'closed')} className="text-xs bg-green-600 hover:bg-green-700 text-white border-0">
                      Client Close & Sign-off
                    </Button>
                  )}
                </div>
              </div>

              {/* Comments Section */}
              <div className="space-y-3">
                <div className="flex items-center gap-2 text-xs font-semibold text-foreground">
                  <MessageSquare className="w-3.5 h-3.5" /> Comments & Resolution Log
                </div>
                <div className="space-y-2 max-h-32 overflow-y-auto">
                  {selectedSnag.comments?.map(c => (
                    <div key={c.id} className="p-2.5 rounded bg-muted/40 text-xs space-y-1">
                      <div className="flex justify-between font-semibold">
                        <span>{c.author_name}</span>
                        <span className="text-muted-foreground font-normal">{formatDate(c.created_at)}</span>
                      </div>
                      <p className="text-muted-foreground">{c.content}</p>
                    </div>
                  ))}
                </div>
                <form onSubmit={handleAddComment} className="flex gap-2">
                  <Input 
                    value={commentText}
                    onChange={(e) => setCommentText(e.target.value)}
                    placeholder="Add a remark or update note..." 
                    className="text-xs h-8"
                  />
                  <Button type="submit" size="sm" className="h-8 text-xs">Post</Button>
                </form>
              </div>
            </div>
            <DialogFooter>
              <Button variant="outline" onClick={() => setSelectedSnagId(null)}>Close</Button>
            </DialogFooter>
          </DialogContent>
        </Dialog>
      )}

      {/* MODAL: Handover Report Generator */}
      <Dialog open={handoverModalOpen} onOpenChange={setHandoverModalOpen}>
        <DialogContent className="max-w-3xl">
          <DialogHeader>
            <DialogTitle>Project Handover Certificate & Snag Summary</DialogTitle>
          </DialogHeader>
          <div className="p-6 bg-white text-slate-800 rounded-lg border border-slate-200 space-y-5 print:p-0">
            {/* Header */}
            <div className="flex justify-between items-start border-b pb-4">
              <div>
                <h2 className="text-xl font-bold text-slate-900">{studioSettings.name}</h2>
                <p className="text-xs text-slate-500">Official Project Handover & Completion Certificate</p>
                <p className="text-xs text-slate-500">{studioSettings.address}</p>
              </div>
              <div className="text-right">
                <span className="px-2.5 py-1 rounded text-xs font-bold bg-green-100 text-green-800">
                  {completionPercent === 100 ? "HANDOVER APPROVED" : "INSPECTION DRAFT"}
                </span>
                <p className="text-xs text-slate-500 mt-2">Date: {formatDate(new Date())}</p>
                <p className="text-xs text-slate-500">Ref: {project?.reference_number}</p>
              </div>
            </div>

            {/* Project Summary */}
            <div className="grid grid-cols-2 gap-4 p-3 bg-slate-50 rounded text-xs">
              <div>
                <span className="text-slate-500 block">Project:</span>
                <strong className="text-slate-900">{project?.name}</strong>
              </div>
              <div>
                <span className="text-slate-500 block">Client:</span>
                <strong className="text-slate-900">{project?.client_name}</strong>
              </div>
              <div>
                <span className="text-slate-500 block">Property Address:</span>
                <span className="text-slate-700">{project?.property_address || "Bengaluru"}</span>
              </div>
              <div>
                <span className="text-slate-500 block">Lead Designer:</span>
                <span className="text-slate-700">{leadDesigner?.full_name || studioSettings.name}</span>
              </div>
            </div>

            {/* Snag Resolution Table */}
            <div>
              <h4 className="text-xs font-bold uppercase tracking-wider text-slate-600 mb-2">Snag Rectification Audit</h4>
              <table className="w-full text-xs">
                <thead>
                  <tr className="border-b bg-slate-100">
                    <th className="p-2 text-left">Item Title</th>
                    <th className="p-2 text-left">Area</th>
                    <th className="p-2 text-center">Priority</th>
                    <th className="p-2 text-center">Status</th>
                    <th className="p-2 text-right">Resolved On</th>
                  </tr>
                </thead>
                <tbody className="divide-y">
                  {snags.map(s => (
                    <tr key={s.id}>
                      <td className="p-2 font-medium">{s.title}</td>
                      <td className="p-2 text-slate-500">{s.room_name}</td>
                      <td className="p-2 text-center capitalize">{s.priority}</td>
                      <td className="p-2 text-center">
                        <span className={cn("px-1.5 py-0.5 rounded text-[10px] font-bold uppercase", s.status === 'closed' ? "bg-green-100 text-green-800" : "bg-amber-100 text-amber-800")}>
                          {s.status}
                        </span>
                      </td>
                      <td className="p-2 text-right text-slate-500">{s.client_closed_at ? formatDate(s.client_closed_at) : "In Progress"}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>

            {/* Signatures */}
            <div className="grid grid-cols-2 gap-8 pt-8 border-t text-xs">
              <div className="space-y-8">
                <p className="text-slate-500">Design Studio Sign-off:</p>
                <div className="border-t border-slate-300 pt-1 font-semibold">
                  {leadDesigner?.full_name || studioSettings.name}, Principal Designer
                </div>
              </div>
              <div className="space-y-8">
                <p className="text-slate-500">Client Acceptance & Handover Signature:</p>
                <div className="border-t border-slate-300 pt-1 font-semibold">
                  {project?.client_name} (Property Owner)
                </div>
              </div>
            </div>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setHandoverModalOpen(false)}>Close</Button>
            <Button onClick={() => window.print()} className="gap-2 gradient-primary border-0">
              <Printer className="w-4 h-4" /> Print / Save Handover Certificate
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

"use client";

import { useState } from "react";
import { Card, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from "@/components/ui/dialog";
import { Plus, ThumbsUp, Heart } from "lucide-react";
import { useAppStore } from "@/lib/store";
import { formatDate } from "@/lib/utils";
import { PhotoInput } from "@/components/files/PhotoInput";
import type { Project, ProjectUpdate } from "@/types";

export default function UpdatesTab({
  project,
  updates,
}: {
  project: Project;
  updates: ProjectUpdate[];
}) {
  const { addProjectUpdate, toggleUpdateReaction } = useAppStore();

  const [postUpdateModalOpen, setPostUpdateModalOpen] = useState(false);
  const [updateForm, setUpdateForm] = useState({
    title: "",
    content: "",
    photoUrl: "",
  });

  const handlePostUpdate = async (e: React.FormEvent) => {
    e.preventDefault();
    const r = await addProjectUpdate({
      project_id: project.id,
      title: updateForm.title,
      content: updateForm.content,
      photos: updateForm.photoUrl ? [updateForm.photoUrl] : [],
    });
    if (r.ok) {
      setUpdateForm({ title: "", content: "", photoUrl: "" });
      setPostUpdateModalOpen(false);
    }
  };

  return (
    <>
      <div className="flex justify-between items-center">
        <span className="text-xs font-bold uppercase tracking-wider text-muted-foreground">Client Progress Feed</span>
        <Button size="sm" onClick={() => setPostUpdateModalOpen(true)} className="gradient-primary border-0 text-xs gap-1.5">
          <Plus className="w-3.5 h-3.5" /> Post Site Update
        </Button>
      </div>

      <div className="space-y-4 max-w-2xl">
        {updates.map(upd => (
          <Card key={upd.id} className="overflow-hidden">
            {upd.photos?.length > 0 && (
              <div className="h-64 bg-muted overflow-hidden">
                <img src={upd.photos[0]} alt="Update" className="w-full h-full object-cover" />
              </div>
            )}
            <CardContent className="p-4 space-y-2">
              <div className="flex justify-between items-start">
                <h4 className="font-bold text-sm text-foreground">{upd.title}</h4>
                <span className="text-[10px] text-muted-foreground">{formatDate(upd.created_at)}</span>
              </div>
              <p className="text-xs text-muted-foreground leading-relaxed">{upd.content}</p>
              <div className="flex items-center gap-3 pt-3 border-t">
                <button 
                  onClick={() => toggleUpdateReaction(upd.id, 'like')}
                  className="flex items-center gap-1 text-xs text-muted-foreground hover:text-primary transition-colors"
                >
                  <ThumbsUp className="w-3.5 h-3.5 text-primary" /> {upd.likes || 0}
                </button>
                <button 
                  onClick={() => toggleUpdateReaction(upd.id, 'love')}
                  className="flex items-center gap-1 text-xs text-muted-foreground hover:text-rose-500 transition-colors"
                >
                  <Heart className="w-3.5 h-3.5 text-rose-500" /> {upd.loved || 0}
                </button>
              </div>
            </CardContent>
          </Card>
        ))}
      </div>

      {/* MODAL: Post Project Update */}
      <Dialog open={postUpdateModalOpen} onOpenChange={setPostUpdateModalOpen}>
        <DialogContent className="max-w-md">
          <DialogHeader>
            <DialogTitle>Post Project Story / Update</DialogTitle>
          </DialogHeader>
          <form onSubmit={handlePostUpdate} className="space-y-3">
            <div className="space-y-1">
              <Label className="text-xs">Update Title</Label>
              <Input 
                required 
                value={updateForm.title} 
                onChange={(e) => setUpdateForm({ ...updateForm, title: e.target.value })}
                placeholder="e.g. Master Bedroom Woodwork Started!"
              />
            </div>
            <div className="space-y-1">
              <PhotoInput
                projectId={project.id}
                label="Site photo"
                onUploaded={(p) => setUpdateForm({ ...updateForm, photoUrl: p })}
              />
            </div>
            <div className="space-y-1">
              <Label className="text-xs">Description</Label>
              <Textarea 
                required 
                value={updateForm.content} 
                onChange={(e) => setUpdateForm({ ...updateForm, content: e.target.value })}
                placeholder="Describe progress made today for the client..."
                rows={3}
              />
            </div>
            <DialogFooter>
              <Button type="button" variant="outline" onClick={() => setPostUpdateModalOpen(false)}>Cancel</Button>
              <Button type="submit" className="gradient-primary border-0">Publish Update</Button>
            </DialogFooter>
          </form>
        </DialogContent>
      </Dialog>
    </>
  );
}
